INSERT INTO Pokemon VALUES (494,0,'Victini',5,100,100,100,100,100,100,'This Pokemon brings victory. It is said that Trainers with Victini always win, regardless of the type of encounter.');
INSERT INTO Pokemon VALUES (495,0,'Snivy',5,45,45,55,63,45,55,'They photosynthesize by bathing their tails in sunlight. When they are not feeling well, their tails droop.');
INSERT INTO Pokemon VALUES (496,0,'Servine',5,60,60,75,83,60,75,'They avoid attacks by sinking into the shadows of thick foliage. They retaliate with masterful whipping techniques.');
INSERT INTO Pokemon VALUES (497,0,'Serperior',5,75,75,95,113,75,95,'They raise their heads to intimidate opponents, but only give it their all when fighting a powerful opponent.');
INSERT INTO Pokemon VALUES (498,0,'Tepig',5,65,63,45,45,45,45,'It blows fire through its nose. When it catches a cold, the fire becomes pitch-black smoke instead.');
INSERT INTO Pokemon VALUES (499,0,'Pignite',5,90,93,55,55,70,55,'Whatever it eats becomes fuel for the flame in its stomach. When it is angered, the intensity of the flame increases.');
INSERT INTO Pokemon VALUES (500,0,'Emboar',5,110,123,65,65,100,65,'It can throw a fire punch by setting its fists on fire with its fiery chin. It cares deeply about its friends.');
INSERT INTO Pokemon VALUES (501,0,'Oshawott',5,55,55,45,45,63,45,'The scalchop on its stomach is made from the same elements as claws. It detaches the scalchop for use as a blade.');
INSERT INTO Pokemon VALUES (502,0,'Dewott',5,75,75,60,60,83,60,'Scalchop techniques differ from one Dewott to another. It never neglects maintaining its scalchops.');
INSERT INTO Pokemon VALUES (503,0,'Samurott',5,95,100,85,70,108,70,'Part of the armor on its anterior legs becomes a giant sword. Its cry alone is enough to intimidate most enemies.');
INSERT INTO Pokemon VALUES (504,0,'Patrat',5,45,55,39,42,35,39,'Extremely cautious, they take shifts to maintain a constant watch of their nest. They feel insecure without a lookout.');
INSERT INTO Pokemon VALUES (505,0,'Watchog',5,60,85,69,77,60,69,'They make the patterns on their bodies shine in order to threaten predators. Keen eyesight lets them see in the dark.');
INSERT INTO Pokemon VALUES (506,0,'Lillipup',5,45,60,45,55,25,45,'The long hair around its face provides an amazing radar that lets it sense subtle changes in its surroundings.');
INSERT INTO Pokemon VALUES (507,0,'Herdier',5,65,80,65,60,35,65,'It loyally follows its Trainer''s orders. For ages, they have helped Trainers raise Pokemon.');
INSERT INTO Pokemon VALUES (508,0,'Stoutland',5,85,110,90,80,45,90,'This extremely wise Pokemon excels at rescuing people stranded at sea or in the mountains.');
INSERT INTO Pokemon VALUES (509,0,'Purrloin',5,41,50,37,66,50,37,'Its cute act is a ruse. When victims let down their guard, they find their items taken. It attacks with sharp claws.');
INSERT INTO Pokemon VALUES (510,0,'Liepard',5,64,88,50,106,88,50,'Stealthily, it sneaks up on its target, striking from behind before its victim has a chance to react.');
INSERT INTO Pokemon VALUES (511,0,'Pansage',5,50,53,48,64,53,48,'It shares the leaf on its head with weary-looking Pokemon. These leaves are known to relieve stress.');
INSERT INTO Pokemon VALUES (512,0,'Simisage',5,75,98,63,101,98,63,'Ill tempered, it fights by swinging its barbed tail around wildly. The leaf growing on its head is very bitter.');
INSERT INTO Pokemon VALUES (513,0,'Pansear',5,50,53,48,64,53,48,'This Pokemon lives in caves in volcanoes. The fire within the tuft on its head can reach 600º F.');
INSERT INTO Pokemon VALUES (514,0,'Simisear',5,75,98,63,101,98,63,'A flame burns inside its body. It scatters embers from its head and tail to sear its opponents.');
INSERT INTO Pokemon VALUES (515,0,'Panpour',5,50,53,48,64,53,48,'It does not thrive in dry environments. It keeps itself damp by shooting water stored in its head tuft from its tail.');
INSERT INTO Pokemon VALUES (516,0,'Simipour',5,75,98,63,101,98,63,'The high-pressure water expelled from its tail is so powerful, it can destroy a concrete wall.');
INSERT INTO Pokemon VALUES (517,0,'Munna',5,76,25,45,24,67,55,'It eats the dreams of people and Pokemon. When it eats a pleasant dreams, it expels pink-colored mist.');
INSERT INTO Pokemon VALUES (518,0,'Musharna',5,116,55,85,29,107,95,'With the mist from its forehead, it can create shapes of things from dreams it has eaten.');
INSERT INTO Pokemon VALUES (519,0,'Pidove',5,50,55,50,43,36,30,'These Pokemon live in cities. They are accustomed to people. Flocks often gather in parks and plazas.');
INSERT INTO Pokemon VALUES (520,0,'Tranquill',5,62,77,62,65,50,42,'Many people believe that, deep in the forest where Tranquill live, there is a peaceful place where there is no war.');
INSERT INTO Pokemon VALUES (521,0,'Unfezant',5,80,115,80,93,65,55,'Males have plumage on their heads. They will never let themselves feel close to anyone other than their Trainers.');
INSERT INTO Pokemon VALUES (522,0,'Blitzle',5,45,60,32,76,50,32,'When thunderclouds cover the sky, it will appear. It can catch lightning with its mane and store the electricity.');
INSERT INTO Pokemon VALUES (523,0,'Zebstrika',5,75,100,63,116,80,63,'This ill-tempered Pokemon is dangerous because when it''s angry, it shoots lightning from its mane in all directions.');
INSERT INTO Pokemon VALUES (524,0,'Roggenrola',5,55,75,85,15,25,25,'They were discovered a hundred years ago in an earthquake fissure. Inside each one is an energy core.');
INSERT INTO Pokemon VALUES (525,0,'Boldore',5,70,105,105,20,50,40,'Because its energy was too great to be contained, the energy leaked and formed orange crystals.');
INSERT INTO Pokemon VALUES (526,0,'Gigalith',5,85,135,130,25,60,80,'The solar energy absorbed by its body''s orange crystals is magnified internally and fired from its mouth.');
INSERT INTO Pokemon VALUES (527,0,'Woobat',5,65,45,43,72,55,43,'Suction from its nostrils enables it to stick to cave walls during sleep. It leaves a heart-shaped mark behind.');
INSERT INTO Pokemon VALUES (528,0,'Swoobat',5,67,57,55,114,77,55,'Anyone who comes into contact with the ultrasonic waves emitted by a courting male experiences a positive mood shift.');
INSERT INTO Pokemon VALUES (529,0,'Drilbur',5,60,85,40,68,30,45,'It makes its way swiftly through the soil by putting both claws together and rotating at high speed.');
INSERT INTO Pokemon VALUES (530,0,'Excadrill',5,110,135,60,88,50,65,'More than 300 feet below the surface, they build mazelike nests. Their activity can be destructive to subway tunnels.');
INSERT INTO Pokemon VALUES (531,0,'Audino',5,103,60,86,50,60,86,'Its auditory sense is astounding. It has a radar-like ability to understand its surrounding through slight sounds.');
INSERT INTO Pokemon VALUES (531,1,'Mega Audino',6,103,60,126,50,80,126,'Its auditory sense is astounding. It has a radar-like ability to understand its surrounding through slight sounds.');
INSERT INTO Pokemon VALUES (532,0,'Timburr',5,75,80,55,35,25,35,'These Pokemon appear at building sites and help out with construction. They always carry squared logs.');
INSERT INTO Pokemon VALUES (533,0,'Gurdurr',5,85,105,85,40,40,50,'They strengthen their bodies by carrying steel beams. They show off their big muscles to their friends.');
INSERT INTO Pokemon VALUES (534,0,'Conkeldurr',5,105,140,95,45,55,65,'They use concrete pillars as walking canes. They know moves that enable them to swing the pillars freely in battle.');
INSERT INTO Pokemon VALUES (535,0,'Tympole',5,50,50,40,64,50,40,'By vibrating its cheeks, it emits sound waves imperceptible to humans. It uses the rhythm of these sounds to talk.');
INSERT INTO Pokemon VALUES (536,0,'Palpitoad',5,75,65,55,69,65,55,'It lives in the water and on land. It uses its long, sticky tongue to capture prey.');
INSERT INTO Pokemon VALUES (537,0,'Seismitoad',5,105,95,75,74,85,75,'It increases the power of its punches by vibrating the bumps on its fists. It can turn a boulder to rubble with one punch.');
INSERT INTO Pokemon VALUES (538,0,'Throh',5,120,100,85,45,30,85,'When they encounter foes bigger than themselves, they try to throw them. They always travel in packs of five.');
INSERT INTO Pokemon VALUES (539,0,'Sawk',5,75,125,75,85,30,75,'Tying their belts gets them pumped and makes their punches more destructive. Disturbing their training angers them.');
INSERT INTO Pokemon VALUES (540,0,'Sewaddle',5,45,53,70,42,40,60,'This Pokemon makes clothes for itself. It chews up leaves and sews them with sticky thread extruded from its mouth.');
INSERT INTO Pokemon VALUES (541,0,'Swadloon',5,55,63,90,42,50,80,'It protects itself from the cold by wrapping up in leaves. It stays on the move, eating leaves in forests.');
INSERT INTO Pokemon VALUES (542,0,'Leavanny',5,75,103,80,92,70,80,'It keeps its eggs warm with heat from fermenting leaves. It also uses leaves to make warm wrappings for Sewaddle.');
INSERT INTO Pokemon VALUES (543,0,'Venipede',5,30,45,59,57,30,39,'It discovers what is going on around it by using the feelers on its head and tail. It is brutally aggresive.');
INSERT INTO Pokemon VALUES (544,0,'Whirlipede',5,40,55,99,47,40,79,'It is usually motionless, but when attacked, it rotates at high speed and then crashes into its opponent.');
INSERT INTO Pokemon VALUES (545,0,'Scolipede',5,60,100,89,112,55,69,'Highly aggressive, it uses the claws near its neck to dig into its opponents and poison them.');
INSERT INTO Pokemon VALUES (546,0,'Cottonee',5,40,27,60,66,37,50,'They go wherever the wind takes them. On rainy days, their bodies are heavier, so they take shelter beneath big trees.');
INSERT INTO Pokemon VALUES (547,0,'Whimsicott',5,60,67,85,116,77,75,'Riding whirlwinds, they appear. These Pokemon sneak through gaps into houses and cause all sorts of mischief.');
INSERT INTO Pokemon VALUES (548,0,'Petilil',5,45,35,50,30,70,50,'Since they prefer moist, nutrient-rich soil, the areas where Petilil live are known to be good for growing plants.');
INSERT INTO Pokemon VALUES (549,0,'Lilligant',5,70,60,75,90,110,75,'The fragrance of the garland on its head has a relaxing effect. It withers if a Trainer does not take good care of it.');
INSERT INTO Pokemon VALUES (550,0,'Red-Striped Basculin',5,70,92,65,98,80,55,'Savage, violent Pokemon, red and blue Basculin are always fighting each other over territory.');
INSERT INTO Pokemon VALUES (550,1,'Blue-Striped Basculin',5,70,92,65,98,80,55,'Even Basculin, which devours everything it can with its huge jaws, is nothing more than food to organisms stronger than itself.');
INSERT INTO Pokemon VALUES (551,0,'Sandile',5,50,72,35,65,35,35,'It moves along below the sand''s surface, except for its nose and eyes. A dark membrane shields its eyes from the sun.');
INSERT INTO Pokemon VALUES (552,0,'Krokorok',5,60,82,45,74,45,45,'The special membrane covering its eyes can sense the heat of objects, so it can see its surroundings, even in darkness.');
INSERT INTO Pokemon VALUES (553,0,'Krookodile',5,95,117,80,92,65,70,'It can expand the focus of its eyes, enabling it to see objects in the far distance as if it were using binoculars.');
INSERT INTO Pokemon VALUES (554,0,'Darumaka',5,70,90,45,50,15,45,'Darumaka''s droppings are hot, so people used to put them in their clothes to keep themselves warm.');
INSERT INTO Pokemon VALUES (554,1,'Galarian Darumaka',8,70,90,45,50,15,45,'The colder they get, the more energetic they are. They freeze their breath to make snowballs, using them as ammo for playful snowball fights.');
INSERT INTO Pokemon VALUES (555,0,'Standard Mode Darmanitan',5,105,140,55,95,30,55,'When weakened in battle, it transforms into a stone statue. Then it sharpens its mind and fights on mentally.');
INSERT INTO Pokemon VALUES (555,1,'Zen Mode Darmanitan',5,105,30,105,55,140,105,'When wounded, it stops moving. It goes as still as stone to meditate, sharpening its mind and spirit.');
INSERT INTO Pokemon VALUES (555,2,'Galarian Standard Mode Darmanitan',8,105,30,105,55,140,105,'On days when blizzards blow through, it comes down to where people live. It stashes food in the snowball on its head, taking it home for later.');
INSERT INTO Pokemon VALUES (555,3,'Galarian Zen Mode Darmanitan',8,105,160,55,135,30,55,'Anger has reignited its atrophied flame sac. This Pokemon spews fire everywhere as it rampages indiscriminately.');
INSERT INTO Pokemon VALUES (556,0,'Maractus',5,75,86,67,60,106,67,'Arid regions are their habitat. They move rhythmically, making a sound similar to maracas.');
INSERT INTO Pokemon VALUES (557,0,'Dwebble',5,50,65,85,55,35,35,'It makes a hole in a suitable rock. If that rock breaks, the Pokemon remains agitated until it locates a replacement.');
INSERT INTO Pokemon VALUES (558,0,'Crustle',5,70,105,125,45,65,75,'It possesses legs of enormous strength, enabling it to carry heavy slabs for many days, even when crossing arid land.');
INSERT INTO Pokemon VALUES (559,0,'Scraggy',5,50,75,70,48,35,70,'It immediately headbutts anyone that makes eye contact with it. Its skull is massively thick.');
INSERT INTO Pokemon VALUES (560,0,'Scrafty',5,65,90,115,58,45,115,'It can smash concrete blocks with its kicking attacks. The one with the biggest crest is the group leader.');
INSERT INTO Pokemon VALUES (561,0,'Sigilyph',5,72,58,80,97,103,80,'The guardians of an ancient city, they use their psychic power to attack enemies that invade their territory.');
INSERT INTO Pokemon VALUES (562,0,'Yamask',5,38,30,85,30,55,65,'These Pokemon arose from the spirits of people interred in graves in past ages. Each retains memories of its former life.');
INSERT INTO Pokemon VALUES (562,1,'Galarian Yamask',8,38,55,85,30,30,65,'A clay slab with cursed engravings took possession of a Yamask. The slab is said to be absorbing the Yamask''s dark power.');
INSERT INTO Pokemon VALUES (563,0,'Cofagrigus',5,58,50,145,30,95,105,'They pretend to be elaborate coffins to teach lessons to grave robbers. Their bodies are covered in pure gold.');
INSERT INTO Pokemon VALUES (564,0,'Tirtouga',5,54,78,103,22,53,45,'About 100 million years ago, these Pokemon swam in oceans. It is thought they also went on land to attack prey.');
INSERT INTO Pokemon VALUES (565,0,'Carracosta',5,74,108,133,32,83,65,'Incredible jaw strength enables them to chew up steel beams and rocks along with their prey.');
INSERT INTO Pokemon VALUES (566,0,'Archen',5,55,112,45,70,74,45,'Revived from a fossil, this Pokemon is thought to be the ancestor of all bird Pokemon.');
INSERT INTO Pokemon VALUES (567,0,'Archeops',5,75,140,65,110,112,65,'It runs better than it flies. It catches prey by running at speeds comparable to those of an automobile.');
INSERT INTO Pokemon VALUES (568,0,'Trubbish',5,50,50,62,65,40,62,'The combination of garbage bags and industrial waste caused the chemical reaction that crated this Pokemon.');
INSERT INTO Pokemon VALUES (569,0,'Garbodor',5,80,95,82,75,60,82,'They absorb garbage and make it part of their bodies. They shoot a poisonous liquid from their right-hand fingertips.');
INSERT INTO Pokemon VALUES (570,0,'Zorua',5,40,65,40,65,80,40,'To protect themselves from danger, they hide their true identities by transforming into people and Pokemon.');
INSERT INTO Pokemon VALUES (571,0,'Zoroark',5,60,105,60,105,120,60,'Each has the ability to fool a large group of people simultaneously. They protect their lair with illusory scenery.');
INSERT INTO Pokemon VALUES (572,0,'Minccino',5,55,50,40,75,40,40,'These Pokemon prefer a tidy habitat. They are always sweeping and dusting, using their tails as brooms.');
INSERT INTO Pokemon VALUES (573,0,'Cinccino',5,75,95,60,115,65,60,'Their white fur feels amazing to touch. Their fur repels dust and prevents static electricity from building up.');
INSERT INTO Pokemon VALUES (574,0,'Gothita',5,45,30,50,45,55,65,'They intently observe both Trainers and Pokemon. Apparently, they are looking at something that only Gothita can see.');
INSERT INTO Pokemon VALUES (575,0,'Gothorita',5,60,45,70,55,75,85,'Starlight is the source of their power. At night, they mark star positions by using psychic power to float stones.');
INSERT INTO Pokemon VALUES (576,0,'Gothitelle',5,70,55,95,65,95,110,'They can predict the future from the placement and movement of the stars. They can see Trainers'' life spans.');
INSERT INTO Pokemon VALUES (577,0,'Solosis',5,45,30,40,20,105,50,'Because their bodies are enveloped in a special liquid, they can survive in any environment.');
INSERT INTO Pokemon VALUES (578,0,'Duosion',5,65,40,50,30,125,60,'When their brains, now divided in two, are thinking the same thoughts, these Pokemon exhibit their maximum power.');
INSERT INTO Pokemon VALUES (579,0,'Reuniclus',5,110,65,75,30,125,85,'These remarkably intelligent Pokemon fight by controlling arms that can grip with rock-crushing power.');
INSERT INTO Pokemon VALUES (580,0,'Ducklett',5,62,44,50,55,44,50,'When attacked, it uses its feathers to splash water, escaping under cover of the spray.');
INSERT INTO Pokemon VALUES (581,0,'Swanna',5,75,87,63,98,87,63,'It administers sharp, powerful pecks with its bill. It whips its long neck to deliver forceful repeated strikes.');
INSERT INTO Pokemon VALUES (582,0,'Vanillite',5,36,50,50,44,65,60,'This Pokemon formed from icicles bathed in energy from the morning sun. It sleeps buried in snow.');
INSERT INTO Pokemon VALUES (583,0,'Vanillish',5,51,65,65,59,80,75,'It conceals itself from enemy eyes by creating many small ice particles and hiding among them.');
INSERT INTO Pokemon VALUES (584,0,'Vanilluxe',5,71,95,85,79,110,95,'If both heads get angry simultaneously, this Pokemon expels a blizzard, burying everything in snow.');
INSERT INTO Pokemon VALUES (585,0,'Spring Form Deerling',5,60,60,50,75,40,50,'The turning of the seasons changes the color and scent of this Pokemon''s fur. People use it to mark the seasons.');
INSERT INTO Pokemon VALUES (585,1,'Summer Form Deerling',5,60,60,50,75,40,50,'The turning of the seasons changes the color and scent of this Pokemon''s fur. People use it to mark the seasons.');
INSERT INTO Pokemon VALUES (585,2,'Autumn Form Deerling',5,60,60,50,75,40,50,'The turning of the seasons changes the color and scent of this Pokemon''s fur. People use it to mark the seasons.');
INSERT INTO Pokemon VALUES (585,3,'Winter Form Deerling',5,60,60,50,75,40,50,'The turning of the seasons changes the color and scent of this Pokemon''s fur. People use it to mark the seasons.');
INSERT INTO Pokemon VALUES (586,0,'Spring Form Sawsbuck',5,80,100,70,95,60,70,'The plants growing on its horns change according to the season. The leaders of the herd possess magnificent horns.');
INSERT INTO Pokemon VALUES (586,1,'Summer Form Sawsbuck',5,80,100,70,95,60,70,'The plants growing on its horns change according to the season. The leaders of the herd possess magnificent horns.');
INSERT INTO Pokemon VALUES (586,2,'Autumn Form Sawsbuck',5,80,100,70,95,60,70,'The plants growing on its horns change according to the season. The leaders of the herd possess magnificent horns.');
INSERT INTO Pokemon VALUES (586,3,'Winter Form Sawsbuck',5,80,100,70,95,60,70,'The plants growing on its horns change according to the season. The leaders of the herd possess magnificent horns.');
INSERT INTO Pokemon VALUES (587,0,'Emolga',5,55,75,60,103,75,60,'They live on treetops and glide using the inside of a cape-like membrane while discharging electricity.');
INSERT INTO Pokemon VALUES (588,0,'Karrablast',5,50,75,45,60,40,45,'When they feel threatened, they spit an acidic liquid to drive attackers away. This Pokemon targets Shelmet.');
INSERT INTO Pokemon VALUES (589,0,'Escavalier',5,70,135,105,20,60,105,'These Pokemon evolve by wearing the shell covering of a Shelmet. The steel armor protects their whole body.');
INSERT INTO Pokemon VALUES (590,0,'Foongus',5,69,55,45,15,55,55,'For some reason, this Pokemon resembles a Poke Ball. They release poison spores to repel those who try to catch them.');
INSERT INTO Pokemon VALUES (591,0,'Amoonguss',5,114,85,70,30,85,80,'They show off their Poke Ball caps to lure prey, but very few Pokemon are fooled by this.');
INSERT INTO Pokemon VALUES (592,0,'Frillish',5,55,40,50,40,65,85,'They paralyze prey with poison, then drag them down to their lairs, five miles below the surface.');
INSERT INTO Pokemon VALUES (593,0,'Jellicent',5,100,60,70,60,85,105,'They propel themselves by expelling absorbed seawater from their bodies. Their favorite food is life energy.');
INSERT INTO Pokemon VALUES (594,0,'Alomomola',5,165,75,80,65,40,45,'Floating in the open sea is how they live. When they find a wounded Pokemon, they embrace it and bring it to shore.');
INSERT INTO Pokemon VALUES (595,0,'Joltik',5,50,47,50,65,57,50,'They attach themselves to large-bodied Pokemon and absorb static electricity, which they store in an electric pouch.');
INSERT INTO Pokemon VALUES (596,0,'Galvantula',5,70,77,60,108,97,60,'They employ an electrically charged web to trap their prey. While it is immobilized by shock, they leisurely consume it.');
INSERT INTO Pokemon VALUES (597,0,'Ferroseed',5,44,50,91,10,24,86,'They stick their spikes into cave walls and absorb the minerals they find in the rock.');
INSERT INTO Pokemon VALUES (598,0,'Ferrothorn',5,74,94,131,20,54,116,'They attach themselves to cave ceilings, firing steel spikes at targets passing beneath them.');
INSERT INTO Pokemon VALUES (599,0,'Klink',5,40,55,70,30,45,60,'Interlocking two bodies and spinning around generates the energy they need to live.');
INSERT INTO Pokemon VALUES (600,0,'Klang',5,60,80,95,50,70,85,'Spinning minigears are rotated at high speed and repeatedly fired away. It is dangerous if the gears don''t return.');
INSERT INTO Pokemon VALUES (601,0,'Klinklang',5,60,100,115,90,70,85,'The gear with the red core is rotated at high speed for a rapid energy charge.');
INSERT INTO Pokemon VALUES (602,0,'Tynamo',5,35,55,40,60,45,40,'These Pokemon move in schools. They have an electricity-generating organ, so they discharge electricity if in danger.');
INSERT INTO Pokemon VALUES (603,0,'Eelektrik',5,65,85,70,40,75,70,'These Pokemon have a big appetite. When they spot their prey, they attack it and paralyze it with electricity.');
INSERT INTO Pokemon VALUES (604,0,'Eelektross',5,85,115,80,50,105,80,'With their sucker mouths, they suck in prey. Then they use their fangs to shock the prey with electricity.');
INSERT INTO Pokemon VALUES (605,0,'Elgyem',5,55,55,55,30,85,55,'This Pokemon had never been seen until it appeared from far in the desert 50 years ago.');
INSERT INTO Pokemon VALUES (606,0,'Beheeyem',5,75,75,75,40,125,95,'It uses psychic power to control an opponent''s brain and tamper with its memories.');
INSERT INTO Pokemon VALUES (607,0,'Litwick',5,50,30,55,20,65,55,'While shining a light and pretending to be a guide, it leeches off the life force of any who follow it.');
INSERT INTO Pokemon VALUES (608,0,'Lampent',5,60,40,60,55,95,60,'It arrives near the moment of death and steals spirit from the body.');
INSERT INTO Pokemon VALUES (609,0,'Chandelure',5,60,55,90,80,145,90,'Being consumed in Chandelure''s flame burns up the spirit, leaving the body behind.');
INSERT INTO Pokemon VALUES (610,0,'Axew',5,46,87,60,57,30,40,'They mark their territory by leaving gashes in trees with their tusks. If a tusk breaks, a new one grows in quickly.');
INSERT INTO Pokemon VALUES (611,0,'Fraxure',5,66,117,70,67,40,50,'Their tusks can shatter rocks. Territory battles between Fraxure can be intensely violent.');
INSERT INTO Pokemon VALUES (612,0,'Haxorus',5,76,147,90,97,60,70,'Their sturdy tusks will stay sharp even if used to cut steel beams. These Pokemon are covered in hard armor.');
INSERT INTO Pokemon VALUES (613,0,'Cubchoo',5,55,70,40,40,60,40,'Its nose is always running. It sniffs the snot back up because the mucus provides the raw material for its moves.');
INSERT INTO Pokemon VALUES (614,0,'Beartic',5,95,130,80,50,70,80,'It freezes its breath to create fangs and claws of ice to fight with. Cold northern areas are its habitat.');
INSERT INTO Pokemon VALUES (615,0,'Cryogonal',5,80,50,50,105,95,135,'They are born in snow clouds. They use chains made of ice crystals to capture prey.');
INSERT INTO Pokemon VALUES (616,0,'Shelmet',5,50,40,85,25,40,65,'It evolves when bathed in an electric-like energy along with Karrablast. The reason is still unknown.');
INSERT INTO Pokemon VALUES (617,0,'Accelgor',5,80,70,40,145,100,60,'Having removed its heavy shell, it becomes very light and can fight with ninja-like movements.');
INSERT INTO Pokemon VALUES (618,0,'Stunfisk',5,109,66,84,32,81,99,'It conceals itself in the mud of the seashore. Then it waits. When prey touch it, it delivers a jolt of energy.');
INSERT INTO Pokemon VALUES (618,1,'Galarian Stunfisk',8,109,81,99,32,66,84,'Its conspicuous lips lure prey in as it lies in wait in the mud. When prey gets close, Stunfisk clamps its jagged steel fins down on them.');
INSERT INTO Pokemon VALUES (619,0,'Mienfoo',5,45,85,50,65,55,50,'They have mastered elegant combos. As they concentrate, their battle moves become swifter and more precise.');
INSERT INTO Pokemon VALUES (620,0,'Mienshao',5,65,125,60,105,95,60,'They use the long fur on their arms as a whip to strike their opponents.');
INSERT INTO Pokemon VALUES (621,0,'Druddigon',5,77,120,90,48,60,90,'It races through narrow caves, using its sharp claws to catch prey. Then skin on its face is harder than a rock.');
INSERT INTO Pokemon VALUES (622,0,'Golett',5,59,74,50,35,35,50,'These Pokemon are thought to have been created by the science of an ancient and mysterious civilization.');
INSERT INTO Pokemon VALUES (623,0,'Golurk',5,89,124,80,55,55,80,'It is said that Golurk were ordered to protect people and Pokemon by the ancient people who made them.');
INSERT INTO Pokemon VALUES (624,0,'Pawniard',5,45,85,70,60,40,40,'They fight at Bisharp''s command. They cling to their prey and inflict damage by sinking their blades into it.');
INSERT INTO Pokemon VALUES (625,0,'Bisharp',5,65,125,100,70,60,70,'Bisharp pursues prey in the company of a large group of Pawniard. Then Bisharp finishes off the prey.');
INSERT INTO Pokemon VALUES (626,0,'Bouffalant',5,95,110,95,55,40,95,'They charge wildly and headbutt everything. They headbutts have enough destructive force to derail a train.');
INSERT INTO Pokemon VALUES (627,0,'Rufflet',5,70,83,50,60,37,50,'They will challenge anything, even strong opponents, without fear. Their frequent fights help them become stronger.');
INSERT INTO Pokemon VALUES (628,0,'Braviary',5,100,123,75,80,57,75,'The more scars they have, the more respect these brave soldiers of the sky get from their peers.');
INSERT INTO Pokemon VALUES (629,0,'Vullaby',5,70,55,75,60,45,65,'They tend to guard their posteriors with suitable bones they have found. They pursue weak Pokemon.');
INSERT INTO Pokemon VALUES (630,0,'Mandibuzz',5,110,65,105,80,55,95,'Watching from the sky, they swoop to strike weakened Pokemon on the ground. They decorate themselves with bones.');
INSERT INTO Pokemon VALUES (631,0,'Heatmor',5,85,97,66,65,105,66,'Using their very hot, flame-covered tongues, they burn through Durant''s steel bodies and consume their insides.');
INSERT INTO Pokemon VALUES (632,0,'Durant',5,58,109,112,109,48,48,'Durant dig nests in mountains. They build their complicated, interconnected tunnels in mazes.');
INSERT INTO Pokemon VALUES (633,0,'Deino',5,52,65,50,38,45,50,'They cannot see, so they tackle and bite to learn about their surroundings. Their bodies are covered in wounds.');
INSERT INTO Pokemon VALUES (634,0,'Zweilous',5,72,85,70,58,65,70,'Since their two heads do not get along and compete with each other for food, they always eat too much.');
INSERT INTO Pokemon VALUES (635,0,'Hydreigon',5,92,105,90,98,125,90,'The heads on their arms do not have brains. They use all three heads to consume and destroy everything.');
INSERT INTO Pokemon VALUES (636,0,'Larvesta',5,55,85,55,60,50,55,'The base of volcanoes is where they make their homes. They shoot fire from their five horns to repel attacking enemies.');
INSERT INTO Pokemon VALUES (637,0,'Volcarona',5,85,60,65,100,135,105,'A sea of fire engulfs the surroundings of their battles, since they use their six wings to scatter their ember scales.');
INSERT INTO Pokemon VALUES (638,0,'Cobalion',5,91,90,129,108,90,72,'It has a body and heart of steel. Its glare is sufficient to make even an unruly Pokemon obey it.');
INSERT INTO Pokemon VALUES (639,0,'Terrakion',5,91,129,90,108,72,90,'Its charge is strong enough to break through a giant castle wall in one blow. This Pokemon is spoken of in legends.');
INSERT INTO Pokemon VALUES (640,0,'Virizion',5,91,90,72,108,90,129,'Its head sprouts horns as sharp as blades. Using whirlwind-like movements, it confounds and swiftly cuts opponents.');
INSERT INTO Pokemon VALUES (641,0,'Incarnate Forme Tornadus',5,79,115,70,111,125,80,'Tornadus expels massive energy from its tail, causing severe storms. Its power is great enough to blow houses away.');
INSERT INTO Pokemon VALUES (641,1,'Therian Forme Tornadus',5,79,100,80,121,110,90,'Tornadus expels massive energy from its tail, causing severe storms. Its power is great enough to blow houses away.');
INSERT INTO Pokemon VALUES (642,0,'Incarnate Forme Thundurus',5,79,115,70,111,125,80,'The spikes on its tail discharge immense bolts of lightning. It flies around the Unova region firing off lightning bolts.');
INSERT INTO Pokemon VALUES (642,1,'Therian Forme Thundurus',5,79,105,70,101,145,80,'The spikes on its tail discharge immense bolts of lightning. It flies around the Unova region firing off lightning bolts.');
INSERT INTO Pokemon VALUES (643,0,'Reshiram',5,100,120,100,90,150,120,'When Reshiram''s tail flares, the heat energy moves the atmosphere and changes the world''s weather.');
INSERT INTO Pokemon VALUES (644,0,'Zekrom',5,100,150,120,90,120,100,'This Pokemon appears in legends. In its tail, it has a giant generator that creates electricity.');
INSERT INTO Pokemon VALUES (645,0,'Incarnate Forme Landorus',5,89,125,90,101,115,80,'The energy that comes pouring from its tail increases the nutrition in the soil, making crops grow to great size.');
INSERT INTO Pokemon VALUES (645,1,'Therian Forme Landorus',5,89,145,90,91,105,80,'The energy that comes pouring from its tail increases the nutrition in the soil, making crops grow to great size.');
INSERT INTO Pokemon VALUES (646,0,'Kyurem',5,125,130,90,95,130,90,'It generates a powerful, freezing energy inside itself, but its body became frozen when the energy leaked out.');
INSERT INTO Pokemon VALUES (646,1,'White Kyurem Kyurem',5,125,120,90,95,170,100,'It has foreseen that a world of truth will arrive for people and Pokemon. It strives to protect that future.');
INSERT INTO Pokemon VALUES (646,2,'Black Kyurem Kyurem',5,125,170,100,95,120,90,'It''s said that this Pokemon battles in order to protect the ideal world that will exist in the future for people and Pokemon.');
INSERT INTO Pokemon VALUES (647,0,'Ordinary Form Keldeo',5,91,72,90,108,129,90,'It crosses the world, running over the surfaces of oceans and rivers. It appears at scenic waterfronts.');
INSERT INTO Pokemon VALUES (647,1,'Resolute Form Keldeo',5,91,72,90,108,129,90,'The power that lay hidden in its body now covers its horn, turning it into a sword that can slice through anything.');
INSERT INTO Pokemon VALUES (648,0,'Aria Forme Meloetta',5,100,77,77,90,128,128,'Many famous songs have been inspired by the melodies that Meloetta plays.');
INSERT INTO Pokemon VALUES (648,1,'Pirouette Forme Meloetta',5,100,128,90,128,77,77,'Many famous songs have been inspired by the melodies that Meloetta plays.');
INSERT INTO Pokemon VALUES (649,0,'Normal Genesect',5,71,120,95,99,120,95,'This ancient bug Pokemon was altered by Team Plasma. They upgraded the cannon on its back.');
INSERT INTO Pokemon VALUES (649,1,'Shock Drive Genesect',5,71,120,95,99,120,95,'This ancient bug Pokemon was altered by Team Plasma. They upgraded the cannon on its back.');
INSERT INTO Pokemon VALUES (649,2,'Burn Drive Genesect',5,71,120,95,99,120,95,'This ancient bug Pokemon was altered by Team Plasma. They upgraded the cannon on its back.');
INSERT INTO Pokemon VALUES (649,3,'Chill Drive Genesect',5,71,120,95,99,120,95,'This ancient bug Pokemon was altered by Team Plasma. They upgraded the cannon on its back.');
INSERT INTO Pokemon VALUES (649,4,'Douse Drive Genesect',5,71,120,95,99,120,95,'This ancient bug Pokemon was altered by Team Plasma. They upgraded the cannon on its back.');
INSERT INTO Pokemon VALUES (650,0,'Chespin',6,56,61,65,38,48,45,'The quills on its head are usually soft. When it flexes them, the points become so hard and sharp that they can pierce rock.');
INSERT INTO Pokemon VALUES (651,0,'Quilladin',6,61,78,95,57,56,58,'They strengthen their lower bodies by running into one another. They are very kind and won''t start fights.');
INSERT INTO Pokemon VALUES (652,0,'Chesnaught',6,88,107,122,64,74,75,'Its Tackle is forceful enough to flip a 50-ton tank. It shields its allies from danger with its own body.');
INSERT INTO Pokemon VALUES (653,0,'Fennekin',6,40,45,40,60,62,60,'As it walks, it munches on a twig in place of a snack. It intimidates opponents by puffing hot air out of its ears.');
INSERT INTO Pokemon VALUES (654,0,'Braixen',6,59,59,58,73,90,70,'When the twig is plucked from its tail, friction sets the twig alight. The flame is used to send signals to its allies.');
INSERT INTO Pokemon VALUES (655,0,'Delphox',6,75,69,72,104,114,100,'It gazes into the flame at the tip of its branch to achieve a focused state, which allows it to see into the future.');
INSERT INTO Pokemon VALUES (656,0,'Froakie',6,41,56,40,71,62,44,'It protects its skin by covering its body in delicate bubbles. Beneath its happy-go-lucky air, it keeps a watchful eye on its surroundings.');
INSERT INTO Pokemon VALUES (657,0,'Frogadier',6,54,63,52,97,83,56,'It can throw bubble-covered pebbles with precise control, hitting empty cans up to a hundred feet away.');
INSERT INTO Pokemon VALUES (658,0,'Greninja',6,72,95,67,122,103,71,'It appears and vanishes with a ninja''s grace. It toys with its enemies using swift movements, while slicing them with throwing stars of sharpest water.');
INSERT INTO Pokemon VALUES (658,1,'Ash-Greninja',7,72,145,67,132,153,71,'It appears and vanishes with a ninja''s grace. It toys with its enemies using swift movements, while slicing them with throwing stars of sharpest water.');
INSERT INTO Pokemon VALUES (659,0,'Bunnelby',6,38,36,38,57,32,36,'It has ears like shovels. Digging holes strengthens its ears so much that they can sever thick roots effortlessly.');
INSERT INTO Pokemon VALUES (660,0,'Diggersby',6,85,56,77,78,50,77,'As powerful as an excavator, its ears can reduce dense bedrock to rubble. When it''s finished digging, it lounges lazily.');
INSERT INTO Pokemon VALUES (661,0,'Fletchling',6,45,50,43,62,40,38,'These friendly Pokemon send signals to one another with beautiful chirps and tail-feather movements.');
INSERT INTO Pokemon VALUES (662,0,'Fletchinder',6,62,73,55,84,56,52,'From its beak, it expels embers that set the tall grass on fire. Then it pounces on the bewildered prey that pop out of the grass.');
INSERT INTO Pokemon VALUES (663,0,'Talonflame',6,78,81,71,126,74,69,'In the fever of an exciting battle, it showers embers from the gaps between its feathers and takes to the air.');
INSERT INTO Pokemon VALUES (664,0,'Scatterbug',6,38,35,40,35,27,25,'When under attack from bird Pokemon, it spews a poisonous black powder that causes paralysis on contact.');
INSERT INTO Pokemon VALUES (665,0,'Spewpa',6,45,22,60,29,27,30,'It lives hidden within thicket shadows. When predators attack, it quickly bristles the fur covering its body in an effort to threaten them.');
INSERT INTO Pokemon VALUES (666,0,'Archipelago Pattern Vivillon',6,80,52,50,89,90,50,'Vivillon with many different patterns are found all over the world. These patterns are affected by the climate of their habitat.');
