INSERT INTO Pokemon VALUES (667,0,'Litleo',6,62,50,58,72,73,54,'They set off on their own from their pride and live by themselves to become stronger. These hot-blooded Pokemon are quick to fight.');
INSERT INTO Pokemon VALUES (668,0,'Pyroar',6,86,68,72,106,109,66,'With fiery breath of more than 6,000 degrees Celsius, they viciously threaten any challenger. The females protect the pride''s cubs.');
INSERT INTO Pokemon VALUES (669,0,'Red Flower Flabebe',6,44,38,39,42,61,79,'When it finds a flower it likes, it dwells on that flower its whole life long. It floats in the wind''s embrace with an untroubled heart.');
INSERT INTO Pokemon VALUES (669,1,'Yellow Flower Flabebe',6,44,38,39,42,61,79,'When it finds a flower it likes, it dwells on that flower its whole life long. It floats in the wind''s embrace with an untroubled heart.');
INSERT INTO Pokemon VALUES (669,2,'Orange Flower Flabebe',6,44,38,39,42,61,79,'When it finds a flower it likes, it dwells on that flower its whole life long. It floats in the wind''s embrace with an untroubled heart.');
INSERT INTO Pokemon VALUES (669,3,'Blue Flower Flabebe',6,44,38,39,42,61,79,'When it finds a flower it likes, it dwells on that flower its whole life long. It floats in the wind''s embrace with an untroubled heart.');
INSERT INTO Pokemon VALUES (669,4,'White Flower Flabebe',6,44,38,39,42,61,79,'When it finds a flower it likes, it dwells on that flower its whole life long. It floats in the wind''s embrace with an untroubled heart.');
INSERT INTO Pokemon VALUES (670,0,'Red Flower Floette',6,54,45,47,52,75,98,'It flutters around fields of flowers and cares for flowers that are starting to wilt. It draws out the power of flowers to battle.');
INSERT INTO Pokemon VALUES (670,1,'Yellow Flower Floette',6,54,45,47,52,75,98,'It flutters around fields of flowers and cares for flowers that are starting to wilt. It draws out the power of flowers to battle.');
INSERT INTO Pokemon VALUES (670,2,'Orange Flower Floette',6,54,45,47,52,75,98,'It flutters around fields of flowers and cares for flowers that are starting to wilt. It draws out the power of flowers to battle.');
INSERT INTO Pokemon VALUES (670,3,'Blue Flower Floette',6,54,45,47,52,75,98,'It flutters around fields of flowers and cares for flowers that are starting to wilt. It draws out the power of flowers to battle.');
INSERT INTO Pokemon VALUES (670,4,'White Flower Floette',6,54,45,47,52,75,98,'It flutters around fields of flowers and cares for flowers that are starting to wilt. It draws out the power of flowers to battle.');
INSERT INTO Pokemon VALUES (670,5,'Eternal Flower Floette',6,74,65,67,92,125,128,'The flower it''s holding can no longer be found blooming anywhere. It''s also thought to contain terrifying power.');
INSERT INTO Pokemon VALUES (671,0,'Red Flower Florges',6,78,65,68,75,112,154,'It claims exquisite flower gardens as its territory, and it obtains power from basking in the energy emitted by flowering plants.');
INSERT INTO Pokemon VALUES (671,1,'Yellow Flower Florges',6,78,65,68,75,112,154,'It claims exquisite flower gardens as its territory, and it obtains power from basking in the energy emitted by flowering plants.');
INSERT INTO Pokemon VALUES (671,2,'Orange Flower Florges',6,78,65,68,75,112,154,'It claims exquisite flower gardens as its territory, and it obtains power from basking in the energy emitted by flowering plants.');
INSERT INTO Pokemon VALUES (671,3,'Blue Flower Florges',6,78,65,68,75,112,154,'It claims exquisite flower gardens as its territory, and it obtains power from basking in the energy emitted by flowering plants.');
INSERT INTO Pokemon VALUES (671,4,'White Flower Florges',6,78,65,68,75,112,154,'It claims exquisite flower gardens as its territory, and it obtains power from basking in the energy emitted by flowering plants.');
INSERT INTO Pokemon VALUES (672,0,'Skiddo',6,66,65,48,52,62,57,'If it has sunshine and water, it doesn''t need to eat, because it can generate energy from the leaves on its back.');
INSERT INTO Pokemon VALUES (673,0,'Gogoat',6,123,100,62,68,97,81,'It can tell how its trainer is feeling by subtle shifts in the grip on its horns. This empathetic sense lets them run as if one being.');
INSERT INTO Pokemon VALUES (674,0,'Pancham',6,67,82,62,43,46,48,'It does its best to be taken seriously by its enemies, but its glare is not sufficiently intimidating. Chewing on a leaf is its trademark.');
INSERT INTO Pokemon VALUES (675,0,'Pangoro',6,95,124,78,58,69,71,'It charges ahead and bashes its opponents like a berserker, uncaring about any hits it might take. Its arms are mighty enough to snap a telephone pole.');
INSERT INTO Pokemon VALUES (676,0,'Natural Form Furfrou',6,75,80,60,102,65,90,'Trimming its fluffy fur not only makes it more elegant but also increases the swiftness of its movements.');
INSERT INTO Pokemon VALUES (676,1,'Heart Trim Furfrou',6,75,80,60,102,65,90,'Trimming its fluffy fur not only makes it more elegant but also increases the swiftness of its movements.');
INSERT INTO Pokemon VALUES (676,2,'Star Trim Furfrou',6,75,80,60,102,65,90,'Trimming its fluffy fur not only makes it more elegant but also increases the swiftness of its movements.');
INSERT INTO Pokemon VALUES (676,3,'Diamond Trim Furfrou',6,75,80,60,102,65,90,'Trimming its fluffy fur not only makes it more elegant but also increases the swiftness of its movements.');
INSERT INTO Pokemon VALUES (676,4,'Debutante Trim Furfrou',6,75,80,60,102,65,90,'Trimming its fluffy fur not only makes it more elegant but also increases the swiftness of its movements.');
INSERT INTO Pokemon VALUES (676,5,'Matron Trim Furfrou',6,75,80,60,102,65,90,'Trimming its fluffy fur not only makes it more elegant but also increases the swiftness of its movements.');
INSERT INTO Pokemon VALUES (676,6,'Dandy Trim Furfrou',6,75,80,60,102,65,90,'Trimming its fluffy fur not only makes it more elegant but also increases the swiftness of its movements.');
INSERT INTO Pokemon VALUES (676,7,'La Reine Trim Furfrou',6,75,80,60,102,65,90,'Trimming its fluffy fur not only makes it more elegant but also increases the swiftness of its movements.');
INSERT INTO Pokemon VALUES (676,8,'Kabuki Trim Furfrou',6,75,80,60,102,65,90,'Trimming its fluffy fur not only makes it more elegant but also increases the swiftness of its movements.');
INSERT INTO Pokemon VALUES (676,9,'Pharaoh Trim Furfrou',6,75,80,60,102,65,90,'Trimming its fluffy fur not only makes it more elegant but also increases the swiftness of its movements.');
INSERT INTO Pokemon VALUES (677,0,'Espurr',6,62,48,54,68,63,60,'The organ that emits its intense psychic power is sheltered by its ears to keep power from leaking out.');
INSERT INTO Pokemon VALUES (678,0,'Male Meowstic',6,74,48,76,104,83,81,'Revealing the eyelike patterns on the insides of its ears will unleash its psychic powers. It normally keeps the patterns hidden, however.');
INSERT INTO Pokemon VALUES (678,1,'Female Meowstic',6,74,48,76,104,83,81,'Females are a bit more selfish and aggressive than males. If they don''t get what they want, they will torment you with their psychic abilities.');
INSERT INTO Pokemon VALUES (679,0,'Honedge',6,45,80,100,28,35,37,'Apparently this Pokemon is born when a departed spirit inhabits a sword. It attaches itself to people and drinks their life force.');
INSERT INTO Pokemon VALUES (680,0,'Doublade',6,59,110,150,35,45,49,'The complex attack patterns of its two swords are unstoppable, even for an opponent greatly accomplished at swordplay.');
INSERT INTO Pokemon VALUES (681,0,'Shield Forme Aegislash',6,60,50,140,60,50,140,'In this defensive stance, Aegislash uses its steel body and a force field of spectral power to reduce the damage of any attack.');
INSERT INTO Pokemon VALUES (681,1,'Blade Forme Aegislash',6,60,140,50,60,140,50,'Once upon a time, a king with an Aegislash reigned over the land. His Pokemon eventually drained him of life, and his kingdom fell with him.');
INSERT INTO Pokemon VALUES (682,0,'Spritzee',6,78,52,60,23,63,65,'It emits a scent that enraptures those who smell it. This fragrance changes depending on what it has eaten.');
INSERT INTO Pokemon VALUES (683,0,'Aromatisse',6,101,72,72,29,99,89,'It devises various scents, pleasant and unpleasant, and emits scents that its enemies dislike in order to gain an edge in battle.');
INSERT INTO Pokemon VALUES (684,0,'Swirlix',6,62,48,66,49,59,57,'To entangle its opponents in battle, it extrudes white threads as sweet and sticky as cotton candy.');
INSERT INTO Pokemon VALUES (685,0,'Slurpuff',6,82,80,86,72,85,75,'It can distinguish the faintest of scents. It puts its sensitive sense of smell to use by helping pastry chefs in their work.');
INSERT INTO Pokemon VALUES (686,0,'Inkay',6,53,54,53,45,37,46,'It flashes the light-emitting spots on its body, which drains its opponent''s will to fight. It takes the opportunity to scuttle away and hide.');
INSERT INTO Pokemon VALUES (687,0,'Malamar',6,86,92,88,73,68,75,'It lures prey close with hypnotic motions, then wraps its tentacles around it before finishing it off with digestive fluids.');
INSERT INTO Pokemon VALUES (688,0,'Binacle',6,42,52,67,50,39,56,'They stretch and then contract, yanking their rocks along with them in bold hops. They eat seaweed that washes up on the shoreline.');
INSERT INTO Pokemon VALUES (689,0,'Barbaracle',6,72,105,115,68,54,86,'Barbaracle''s legs and hands have minds of their own, and they will move independently. But they usually follow the head''s orders.');
INSERT INTO Pokemon VALUES (690,0,'Skrelp',6,50,60,60,30,60,60,'Camouflaged as rotten kelp, they spray liquid poison on prey that approaches unawares and then finish it off.');
INSERT INTO Pokemon VALUES (691,0,'Dragalge',6,65,75,90,44,97,123,'Their poison is strong enough to eat through the hull of a tanker, and they spit it indiscriminately at anything that enters their territory.');
INSERT INTO Pokemon VALUES (692,0,'Clauncher',6,50,53,62,44,58,63,'Through controlled expulsions of internal gas, it can expel water like a pistol shot. At close distances, it can shatter rock.');
INSERT INTO Pokemon VALUES (693,0,'Clawitzer',6,71,73,88,59,120,89,'By expelling water from the nozzle in the back of its claw, it can move at a speed of 60 knots.');
INSERT INTO Pokemon VALUES (694,0,'Helioptile',6,44,38,33,70,61,43,'They make their home in deserts. They can generate their energy from basking in the sun, so eating food is not a requirement.');
INSERT INTO Pokemon VALUES (695,0,'Heliolisk',6,62,55,52,109,109,94,'They flare their frills and generate energy. A single Heliolisk can generate sufficient electricity to power a skyscraper.');
INSERT INTO Pokemon VALUES (696,0,'Tyrunt',6,58,89,77,48,45,45,'Its immense jaws have enough destructive force that it can chew up an automobile. It lived 100 million years ago.');
INSERT INTO Pokemon VALUES (697,0,'Tyrantrum',6,82,121,119,71,69,59,'Thanks to its gargantuan jaws, which could shred thick metal plates as if they were paper, it was invincible in the ancient world it once inhabited.');
INSERT INTO Pokemon VALUES (698,0,'Amaura',6,77,59,50,46,67,63,'This ancient Pokemon was restored from part of its body that had been frozen in ice for over 100 million years.');
INSERT INTO Pokemon VALUES (699,0,'Aurorus',6,123,77,72,58,99,92,'Using its diamond-shaped crystals, it can instantly create a wall of ice to block an opponent''s attack.');
INSERT INTO Pokemon VALUES (700,0,'Sylveon',6,95,65,65,60,110,130,'Its ribbonlike feelers give off an aura that weakens hostility in its prey, causing them to let down their guard. Then it attacks.');
INSERT INTO Pokemon VALUES (701,0,'Hawlucha',6,78,92,75,118,74,63,'With its wings, it controls its position in the air. It likes to attack from above, a maneuver that is difficult to defend against.');
INSERT INTO Pokemon VALUES (702,0,'Dedenne',6,67,58,57,101,81,67,'Its whiskers serve as antennas. By sending and receiving electrical waves, it can communicate with others over vast distances.');
INSERT INTO Pokemon VALUES (703,0,'Carbink',6,50,50,150,50,50,150,'Born from the high temperatures and pressures deep underground, it defends itself by firing beams from the jewel part of its body.');
INSERT INTO Pokemon VALUES (704,0,'Goomy',6,45,50,35,40,55,75,'Its source of protection is its slimy, germ-laden mucous membrane. Anyone who touches it needs some thorough hand-washing.');
INSERT INTO Pokemon VALUES (705,0,'Sliggoo',6,68,75,53,60,83,113,'This Pokemon''s mucous can dissolve anything. Toothless, it sprays mucous on its prey. Once they''re nicely dissolved, it slurps them up.');
INSERT INTO Pokemon VALUES (706,0,'Goodra',6,90,100,70,80,110,150,'It gets picked on because it''s meek. But then, whoever teased it gets to feel the full force of its horns and a good swatting from its thick tail.');
INSERT INTO Pokemon VALUES (707,0,'Klefki',6,57,80,91,75,80,87,'It never lets go of a key that it likes, so people give it the keys to vaults and safes as a way to prevent crime.');
INSERT INTO Pokemon VALUES (708,0,'Phantump',6,43,70,48,38,50,60,'These Pokemon are stumps possessed by the spirits of children who died in the forest. Their cries sound like eerie screams.');
INSERT INTO Pokemon VALUES (709,0,'Trevenant',6,85,110,76,56,65,82,'Through its roots, it exerts control over other trees. A deadly curse falls upon anyone cutting down trees in forests where Trevenant dwell.');
INSERT INTO Pokemon VALUES (710,0,'Small Size Pumpkaboo',6,44,66,70,56,44,55,'When taking spirits to the afterlife, small Pumpkaboo prefer the spirits of children to those of adults.');
INSERT INTO Pokemon VALUES (710,1,'Average Size Pumpkaboo',6,49,66,70,51,44,55,'Spirits that wander this world are placed into Pumpkaboo''s body. They''re then moved on to the afterlife.');
INSERT INTO Pokemon VALUES (710,2,'Large Size Pumpkaboo',6,54,66,70,46,44,55,'When taking spirits to the afterlife, large Pumpkaboo prefer the spirits of adults to those of children.');
INSERT INTO Pokemon VALUES (710,3,'Super Size Pumpkaboo',6,59,66,70,41,44,55,'Massive Pumpkaboo are said to be the product of areas where a great number of lost souls lingered.');
INSERT INTO Pokemon VALUES (711,0,'Small Size Gourgeist',6,55,85,122,99,58,75,'Small Gourgeist pretend to be children to fool adults. Anyone who falls for the act gets carried away to the hereafter.');
INSERT INTO Pokemon VALUES (711,1,'Average Size Gourgeist',6,65,90,122,84,58,75,'Eerie cries emanate from its body in the dead of night. The sounds are said to be the wails of spirits who are suffering in the afterlife.');
INSERT INTO Pokemon VALUES (711,2,'Large Size Gourgeist',6,75,95,122,69,58,75,'Large Gourgeist put on the guise of adults, taking the hands of children to lead them to the afterlife.');
INSERT INTO Pokemon VALUES (711,3,'Super Size Gourgeist',6,85,100,122,54,58,75,'Supersized Gourgeist aren''t picky. They will forcefully drag anyone off to the afterlife.');
INSERT INTO Pokemon VALUES (712,0,'Bergmite',6,55,69,85,28,32,35,'It blocks opponents'' attacks with the ice that shields its body. It uses cold air to repair any cracks with new ice.');
INSERT INTO Pokemon VALUES (713,0,'Avalugg',6,95,117,184,28,44,46,'Its ice-covered body is as hard as steel. Its cumbersome frame crushes anything that stands in its way.');
INSERT INTO Pokemon VALUES (714,0,'Noibat',6,40,30,35,55,45,40,'Even a robust wrestler will become dizzy and unable to stand when exposed to its 200,000-hertz ultrasonic waves.');
INSERT INTO Pokemon VALUES (715,0,'Noivern',6,85,70,80,123,97,80,'They fly around on moonless nights and attack careless prey. Nothing can beat them in a battle in the dark.');
INSERT INTO Pokemon VALUES (716,0,'Neutral Mode Xerneas',6,126,131,95,99,131,98,'Legends say it can share eternal life. It slept for a thousand years in the form of a tree before its revival.');
INSERT INTO Pokemon VALUES (716,1,'Active Mode Xerneas',6,126,131,95,99,131,98,'Legends say it can share eternal life. It slept for a thousand years in the form of a tree before its revival.');
INSERT INTO Pokemon VALUES (717,0,'Yveltal',6,126,131,95,99,131,98,'When its life comes to an end, it absorbs the life energy of every living thing and turns into a cocoon once more.');
INSERT INTO Pokemon VALUES (718,0,'50% Forme Zygarde',6,108,100,121,95,81,95,'It''s thought to be monitoring the ecosystem. There are rumors that even greater power lies hidden within it.');
INSERT INTO Pokemon VALUES (718,1,'10% Forme Zygarde',7,54,100,71,115,61,85,'This is Zygarde when about 10% of its pieces have been assembled. It leaps at its opponent''s chest and sinks its sharp fangs into them.');
INSERT INTO Pokemon VALUES (718,2,'Complete Forme Zygarde',7,216,100,121,85,91,95,'This is Zygarde''s perfected form. From the orifice on its chest, it radiates high-powered energy that eliminates everything.');
INSERT INTO Pokemon VALUES (719,0,'Diancie',6,50,100,150,50,100,150,'A sudden transformation of Carbink, its pink, glimmering body is said to be the loveliest sight in the whole world.');
INSERT INTO Pokemon VALUES (719,1,'Mega Diancie',6,50,160,110,110,160,110,'A sudden transformation of Carbink, its pink, glimmering body is said to be the loveliest sight in the whole world.');
INSERT INTO Pokemon VALUES (720,0,'Hoopa Confined Hoopa',6,80,110,60,70,150,130,'This troublemaker sends anything and everything to faraway places using its loop, which can warp space.');
INSERT INTO Pokemon VALUES (720,1,'Hoopa Unbound Hoopa',6,80,160,60,80,170,130,'This troublemaker sends anything and everything to faraway places using its loop, which can warp space.');
INSERT INTO Pokemon VALUES (721,0,'Volcanion',6,80,110,120,70,130,90,'It lets out billows of steam and disappears into the dense fog. It''s said to live in mountains where humans do not tread.');
INSERT INTO Pokemon VALUES (722,0,'Rowlet',7,68,55,55,42,50,50,'It sends its feathers, which are as sharp as blades, flying in attack. Its legs are strong, so its kicks are also formidable.');
INSERT INTO Pokemon VALUES (723,0,'Dartrix',7,78,75,75,52,70,70,'A bit of a dandy, it spends its free time preening its wings. Its preoccupation with any dirt on its plumage can leave it unable to battle.');
INSERT INTO Pokemon VALUES (724,0,'Decidueye',7,78,107,75,70,100,100,'It fires arrow quills from its wings with such precision, they can pierce a pebble at distances over a hundred yards.');
INSERT INTO Pokemon VALUES (725,0,'Litten',7,45,65,40,70,60,40,'Its coat regrows twice a year. When the time comes, Litten sets its own body on fire and burns away the old fur.');
INSERT INTO Pokemon VALUES (726,0,'Torracat',7,65,85,50,90,80,50,'It can act spoiled if it grows close to its Trainer. A powerful Pokemon, its sharp claws can leave its Trainer''s whole body covered in scratches.');
INSERT INTO Pokemon VALUES (727,0,'Incineroar',7,95,115,90,60,80,90,'Although it''s rough mannered and egotistical, it finds beating down unworthy opponents boring. It gets motivated for stronger opponents.');
INSERT INTO Pokemon VALUES (728,0,'Popplio',7,50,54,54,40,66,56,'This Pokemon snorts body fluids from its nose, blowing balloons to smash into its foes. It''s famous for being a hard worker.');
INSERT INTO Pokemon VALUES (729,0,'Brionne',7,60,69,69,50,91,81,'It gets excited when it sees a dance it doesn''t know. This hard worker practices diligently until it can learn that dance.');
INSERT INTO Pokemon VALUES (730,0,'Primarina',7,80,74,74,60,126,116,'It controls its water balloons with song. The melody is learned from others of its kind and is passed down from one generation to the next.');
INSERT INTO Pokemon VALUES (731,0,'Pikipek',7,35,75,30,65,30,30,'It pecks at trees with its hard beak. You can get some idea of its mood or condition from the rhythm of its pecking.');
INSERT INTO Pokemon VALUES (732,0,'Trumbeak',7,55,85,50,75,40,50,'It eats berries and stores their seeds in its beak. When it encounters enemies or prey, it fires off all the seeds in a burst.');
INSERT INTO Pokemon VALUES (733,0,'Toucannon',7,80,120,75,60,75,75,'They smack beaks with others of their kind to communicate. The strength and number of hits tell each other how they feel.');
INSERT INTO Pokemon VALUES (734,0,'Yungoos',7,48,70,30,45,30,30,'Its stomach takes up most of its long torso. It''s a big eater, so the amount Trainers have to spend on its food is no laughing matter.');
INSERT INTO Pokemon VALUES (735,0,'Gumshoos',7,88,110,60,45,55,60,'When it finds a trace of its prey, it patiently stakes out the location... but it''s always snoozing by nightfall.');
INSERT INTO Pokemon VALUES (736,0,'Grubbin',7,47,62,45,46,55,45,'It spits a sticky thread to stop opponents in their tracks, and then it grabs them in its sharp, sturdy mandibles to take them down.');
INSERT INTO Pokemon VALUES (737,0,'Charjabug',7,57,82,95,36,55,75,'It buries itself in fallen leaves and barely moves, munching away on humus. If you accidentally step on one, you''ll get a shock!');
INSERT INTO Pokemon VALUES (738,0,'Vikavolt',7,77,70,90,43,145,75,'It zips around, on sharp lookout for an opening. It concentrates electrical energy within its large jaws and uses it to zap its enemies.');
INSERT INTO Pokemon VALUES (739,0,'Crabrawler',7,47,82,57,63,42,47,'It punches so much, its pincers often come off from overuse, but they grow back quickly. What little meat they contain is rich and delicious.');
INSERT INTO Pokemon VALUES (740,0,'Crabominable',7,97,132,77,43,62,67,'It aimed for the top but got lost and ended up on a snowy mountain. Being forced to endure the cold, this Pokemon evolved and grew fur.');
INSERT INTO Pokemon VALUES (741,0,'Baile Style Oricorio',7,75,70,70,93,98,70,'It beats its wings together to create fire. As it moves in the steps of its beautiful dance, it bathes opponents in intense flames.');
INSERT INTO Pokemon VALUES (741,1,'Pom-Pom Style Oricorio',7,75,70,70,93,98,70,'It creates an electric charge by rubbing its feathers together. It dances over to its enemies and delivers shocking electrical punches.');
INSERT INTO Pokemon VALUES (741,2,'Pa''u Style Oricorio',7,75,70,70,93,98,70,'This Oricorio relaxes by swaying gently. This increases its psychic energy, which it then fires at its enemies.');
INSERT INTO Pokemon VALUES (741,3,'Sensu Style Oricorio',7,75,70,70,93,98,70,'It summons the dead with its dreamy dancing. From their malice, it draws power with which to curse its enemies.');
INSERT INTO Pokemon VALUES (742,0,'Cutiefly',7,40,45,40,84,55,40,'It feeds on the nectar and pollen of flowers. Because it''s able to sense auras, it can identify which flowers are about to bloom.');
INSERT INTO Pokemon VALUES (743,0,'Ribombee',7,60,55,60,124,95,70,'Rain makes pollen damp, so Ribombee hates rain. When it sees ominous clouds, it finds a hollow in a tree, where it waits stock-still.');
INSERT INTO Pokemon VALUES (744,0,'Rockruff',7,45,65,40,60,30,40,'This Pokemon has lived with people since times long ago. It can sense when its Trainer is in the dumps and will stick close by its Trainer''s side.');
INSERT INTO Pokemon VALUES (745,0,'Midday Form Lycanroc',7,75,115,65,112,55,65,'Its quick movements confuse its enemies. Well equipped with claws and fangs, it also uses the sharp rocks in its mane as weapons.');
INSERT INTO Pokemon VALUES (745,1,'Midnight Form Lycanroc',7,85,115,75,82,55,75,'It goads its enemies into attacking, withstands the hits, and in return, delivers a headbutt, crushing their bones with its rocky mane.');
INSERT INTO Pokemon VALUES (745,2,'Dusk Form Lycanroc',7,75,117,65,110,55,65,'Bathed in the setting sun of evening, Lycanroc has undergone a special kind of evolution. An intense fighting spirit underlies its calmness.');
INSERT INTO Pokemon VALUES (746,0,'Solo Form Wishiwashi',7,45,20,20,40,25,25,'It''s awfully weak and notably tasty, so everyone is always out to get it. As it happens, anyone trying to bully it receives a painful lesson.');
INSERT INTO Pokemon VALUES (746,1,'School Form Wishiwashi',7,45,140,130,30,140,135,'Weak Wishiwashi school together to concentrate their power. Their united force makes them the demon of the sea, feared near and far.');
INSERT INTO Pokemon VALUES (747,0,'Mareanie',7,50,53,62,45,43,52,'It plunges the poison spike on its head into its prey. When the prey has weakened, Mareanie deals the finishing blow with its 10 tentacles.');
INSERT INTO Pokemon VALUES (748,0,'Toxapex',7,50,63,152,35,53,142,'Those attacked by Toxapex''s poison will suffer intense pain for three days and three nights. Post-recovery, there will be some aftereffects.');
INSERT INTO Pokemon VALUES (749,0,'Mudbray',7,70,100,70,45,45,55,'It loves playing in the mud. If it isn''t showered with mud on a daily basis, it gets stressed out and stops listening to its Trainer.');
INSERT INTO Pokemon VALUES (750,0,'Mudsdale',7,100,125,100,35,55,85,'It remains calm and unmoving no matter the situation. It mixes dirt with the saliva in its mouth to make a special kind of mud.');
INSERT INTO Pokemon VALUES (751,0,'Dewpider',7,38,40,52,27,40,72,'When two Dewpider meet, they display their water bubbles to each other. Then the one with the smaller bubble gets out of the other''s way.');
INSERT INTO Pokemon VALUES (752,0,'Araquanid',7,68,70,92,42,50,132,'It delivers headbutts with the water bubble on its head. Small Pokemon get sucked into the bubble, where they drown.');
INSERT INTO Pokemon VALUES (753,0,'Fomantis',7,40,55,35,35,50,35,'When the sun rises, Fomantis spreads its four leaves and bathes in the sunlight. The tip of its head has a pleasant aroma.');
INSERT INTO Pokemon VALUES (754,0,'Lurantis',7,70,105,90,45,80,90,'It requires a lot of effort to maintain Lurantis''s vivid coloring, but some collectors enjoy this work and treat it as their hobby.');
INSERT INTO Pokemon VALUES (755,0,'Morelull',7,40,35,55,15,65,75,'It scatters its shining spores around itself. Even though they''re dangerous, nighttime tours of forests where Morelull live are popular.');
INSERT INTO Pokemon VALUES (756,0,'Shiinotic',7,60,45,80,30,90,100,'It puts its prey to sleep and siphons off their vitality through the tip of its arms. If one of its kind is weakened, it helps by sending it vitality.');
INSERT INTO Pokemon VALUES (757,0,'Salandit',7,48,44,40,77,71,40,'It burns its bodily fluids to create a poisonous gas. When its enemies become disoriented from inhaling the gas, it attacks them.');
INSERT INTO Pokemon VALUES (758,0,'Salazzle',7,68,64,60,117,111,60,'Filled with pheromones, its poisonous gas can be diluted to use in the production of luscious perfumes.');
INSERT INTO Pokemon VALUES (759,0,'Stufful',7,70,75,50,50,45,50,'Despite its adorable appearance, when it gets angry and flails about, its arms and legs could knock a pro wrestler sprawling.');
INSERT INTO Pokemon VALUES (760,0,'Bewear',7,120,125,80,60,55,60,'It waves its hands wildly in intimidation and warning. Life is over for anyone who doesn''t run away as fast as possible.');
INSERT INTO Pokemon VALUES (761,0,'Bounsweet',7,42,30,38,32,30,38,'Because of its sweet, delicious aroma, bird Pokemon are always after it, but it''s not intelligent enough to care.');
INSERT INTO Pokemon VALUES (762,0,'Steenee',7,52,40,48,62,40,48,'It''s protected by its hard sepals, so it plays with bird Pokemon without worry. They peck it relentlessly, but it doesn''t care.');
INSERT INTO Pokemon VALUES (763,0,'Tsareena',7,72,120,98,72,50,98,'A Pokemon with an aggressive personality and a mastery of kicking, it cackles every time it kicks an opponent.');
INSERT INTO Pokemon VALUES (764,0,'Comfey',7,51,52,90,100,82,110,'Baths prepared with the flowers from its vine have a relaxing effect, so this Pokemon is a hit with many people.');
INSERT INTO Pokemon VALUES (765,0,'Oranguru',7,90,60,80,60,90,110,'It normally spends its time meditating in the treetops. It throws Poke Balls and gives other Pokemon orders as it pleases.');
INSERT INTO Pokemon VALUES (766,0,'Passimian',7,100,120,90,80,40,60,'Berries are its weapons as well as the staple of its diet. The one that can throw a berry the farthest is the boss of the troop.');
INSERT INTO Pokemon VALUES (767,0,'Wimpod',7,25,35,40,80,20,30,'This Pokemon is a coward. As it desperately dashes off, the flailing of its many legs leaves a sparkling clean path in its wake.');
INSERT INTO Pokemon VALUES (768,0,'Golisopod',7,75,125,140,40,60,90,'It battles skillfully with its six arms, but spends most of its time peacefully meditating in caves deep beneath the sea.');
INSERT INTO Pokemon VALUES (769,0,'Sandygast',7,55,55,80,15,70,45,'It likes the shovel on its head, so Sandygast will get serious and fight any children who come to take it back.');
INSERT INTO Pokemon VALUES (770,0,'Palossand',7,85,75,110,35,100,75,'Buried beneath the castle are masses of dried-up bones from those whose vitality it has drained.');
INSERT INTO Pokemon VALUES (771,0,'Pyukumuku',7,55,60,130,5,30,130,'It lives in shallow seas, such as areas near a beach. It can eject its internal organs, which it uses to engulf its prey or battle enemies.');
INSERT INTO Pokemon VALUES (772,0,'Type: Null',7,95,95,95,59,95,95,'The heavy control mask it wears suppresses its intrinsic capabilities. This Pokemon has some hidden special power.');
INSERT INTO Pokemon VALUES (773,0,'Type: Normal Silvally',7,95,95,95,95,95,95,'Its trust in its partner is what awakens it. This Pokemon is capable of changing its type, a flexibility that is well displayed in battle.');
INSERT INTO Pokemon VALUES (773,1,'Type: Fighting Silvally',7,95,95,95,95,95,95,'Its trust in its partner is what awakens it. This Pokemon is capable of changing its type, a flexibility that is well displayed in battle.');
INSERT INTO Pokemon VALUES (773,2,'Type: Flying Silvally',7,95,95,95,95,95,95,'Its trust in its partner is what awakens it. This Pokemon is capable of changing its type, a flexibility that is well displayed in battle.');
INSERT INTO Pokemon VALUES (773,3,'Type: Poison Silvally',7,95,95,95,95,95,95,'Its trust in its partner is what awakens it. This Pokemon is capable of changing its type, a flexibility that is well displayed in battle.');
INSERT INTO Pokemon VALUES (773,4,'Type: Ground Silvally',7,95,95,95,95,95,95,'Its trust in its partner is what awakens it. This Pokemon is capable of changing its type, a flexibility that is well displayed in battle.');
INSERT INTO Pokemon VALUES (773,5,'Type: Rock Silvally',7,95,95,95,95,95,95,'Its trust in its partner is what awakens it. This Pokemon is capable of changing its type, a flexibility that is well displayed in battle.');
INSERT INTO Pokemon VALUES (773,6,'Type: Bug Silvally',7,95,95,95,95,95,95,'Its trust in its partner is what awakens it. This Pokemon is capable of changing its type, a flexibility that is well displayed in battle.');
INSERT INTO Pokemon VALUES (773,7,'Type: Ghost Silvally',7,95,95,95,95,95,95,'Its trust in its partner is what awakens it. This Pokemon is capable of changing its type, a flexibility that is well displayed in battle.');
INSERT INTO Pokemon VALUES (773,8,'Type: Steel Silvally',7,95,95,95,95,95,95,'Its trust in its partner is what awakens it. This Pokemon is capable of changing its type, a flexibility that is well displayed in battle.');
INSERT INTO Pokemon VALUES (773,9,'Type: Unknown Silvally',7,95,95,95,95,95,95,'Its trust in its partner is what awakens it. This Pokemon is capable of changing its type, a flexibility that is well displayed in battle.');
INSERT INTO Pokemon VALUES (773,10,'Type: Fire Silvally',7,95,95,95,95,95,95,'Its trust in its partner is what awakens it. This Pokemon is capable of changing its type, a flexibility that is well displayed in battle.');
INSERT INTO Pokemon VALUES (773,11,'Type: Water Silvally',7,95,95,95,95,95,95,'Its trust in its partner is what awakens it. This Pokemon is capable of changing its type, a flexibility that is well displayed in battle.');
INSERT INTO Pokemon VALUES (773,12,'Type: Grass Silvally',7,95,95,95,95,95,95,'Its trust in its partner is what awakens it. This Pokemon is capable of changing its type, a flexibility that is well displayed in battle.');
INSERT INTO Pokemon VALUES (773,13,'Type: Electric Silvally',7,95,95,95,95,95,95,'Its trust in its partner is what awakens it. This Pokemon is capable of changing its type, a flexibility that is well displayed in battle.');
INSERT INTO Pokemon VALUES (773,14,'Type: Psychic Silvally',7,95,95,95,95,95,95,'Its trust in its partner is what awakens it. This Pokemon is capable of changing its type, a flexibility that is well displayed in battle.');
INSERT INTO Pokemon VALUES (773,15,'Type: Ice Silvally',7,95,95,95,95,95,95,'Its trust in its partner is what awakens it. This Pokemon is capable of changing its type, a flexibility that is well displayed in battle.');
INSERT INTO Pokemon VALUES (773,16,'Type: Dragon Silvally',7,95,95,95,95,95,95,'Its trust in its partner is what awakens it. This Pokemon is capable of changing its type, a flexibility that is well displayed in battle.');
INSERT INTO Pokemon VALUES (773,17,'Type: Dark Silvally',7,95,95,95,95,95,95,'Its trust in its partner is what awakens it. This Pokemon is capable of changing its type, a flexibility that is well displayed in battle.');
INSERT INTO Pokemon VALUES (773,18,'Type: Fairy Silvally',7,95,95,95,95,95,95,'Its trust in its partner is what awakens it. This Pokemon is capable of changing its type, a flexibility that is well displayed in battle.');
INSERT INTO Pokemon VALUES (774,0,'Meteor Form Minior',7,60,60,100,60,60,100,'Originally making its home in the ozone layer, it hurtles to the ground when the shell enclosing its body grows too heavy.');
INSERT INTO Pokemon VALUES (774,1,'Red Core Minior',7,60,100,60,120,100,60,'If its core stays exposed, it will soon die off. It''s possible that it may survive if it''s put into a Poke Ball quickly enough.');
INSERT INTO Pokemon VALUES (774,2,'Orange Core Minior',7,60,100,60,120,100,60,'If its core stays exposed, it will soon die off. It''s possible that it may survive if it''s put into a Poke Ball quickly enough.');
INSERT INTO Pokemon VALUES (774,3,'Yellow Core Minior',7,60,100,60,120,100,60,'If its core stays exposed, it will soon die off. It''s possible that it may survive if it''s put into a Poke Ball quickly enough.');
INSERT INTO Pokemon VALUES (774,4,'Green Core Minior',7,60,100,60,120,100,60,'If its core stays exposed, it will soon die off. It''s possible that it may survive if it''s put into a Poke Ball quickly enough.');
INSERT INTO Pokemon VALUES (774,5,'Blue Core Minior',7,60,100,60,120,100,60,'If its core stays exposed, it will soon die off. It''s possible that it may survive if it''s put into a Poke Ball quickly enough.');
INSERT INTO Pokemon VALUES (774,6,'Indigo Core Minior',7,60,100,60,120,100,60,'If its core stays exposed, it will soon die off. It''s possible that it may survive if it''s put into a Poke Ball quickly enough.');
INSERT INTO Pokemon VALUES (774,7,'Violet Core Minior',7,60,100,60,120,100,60,'If its core stays exposed, it will soon die off. It''s possible that it may survive if it''s put into a Poke Ball quickly enough.');
INSERT INTO Pokemon VALUES (775,0,'Komala',7,65,115,65,65,75,95,'It remains asleep from birth to death as a result of the sedative properties of the leaves that form its diet.');
INSERT INTO Pokemon VALUES (776,0,'Turtonator',7,60,78,135,36,91,85,'It lives in volcanoes and eats sulfur and other minerals. Materials from the food it eats form the basis of its explosive shell.');
INSERT INTO Pokemon VALUES (777,0,'Togedemaru',7,65,98,63,96,40,73,'The long hairs on its back act as lightning rods. The bolts of lightning it attracts are stored as energy in its electric sac.');
INSERT INTO Pokemon VALUES (778,0,'Disguised Form Mimikyu',7,55,90,80,96,50,105,'A lonely Pokemon, it conceals its terrifying appearance beneath an old rag so it can get closer to people and other Pokemon.');
INSERT INTO Pokemon VALUES (778,1,'Busted Form Mimikyu',7,55,90,80,96,50,105,'Sad that its true identity may be exposed, Mimikyu will mercilessly seek revenge on any opponent that breaks its neck.');
INSERT INTO Pokemon VALUES (779,0,'Bruxish',7,68,105,70,92,70,70,'When it unleashes its psychic power from the protuberance on its head, the grating sound of grinding teeth echoes through the area.');
INSERT INTO Pokemon VALUES (780,0,'Drampa',7,78,60,85,36,135,91,'This Pokemon is friendly to people and loves children most of all. It comes from deep in the mountains to play with children it likes in town.');
INSERT INTO Pokemon VALUES (781,0,'Dhelmise',7,70,131,100,40,86,90,'The soul of seaweed adrift in the waves became reborn as this Pokemon. It maintains itself with new infusions of seabed detritus and seaweed.');
INSERT INTO Pokemon VALUES (782,0,'Jangmo-o',7,45,55,65,45,45,45,'It expresses its feelings by smacking its scales. Metallic sounds echo through the tall mountains where Jangmo-o lives.');
INSERT INTO Pokemon VALUES (783,0,'Hakamo-o',7,55,75,90,65,65,70,'It sheds and regrows its scales on a continuous basis. The scales become harder and sharper each time they''re regrown.');
INSERT INTO Pokemon VALUES (784,0,'Kommo-o',7,75,110,125,85,100,105,'Its rigid scales function as offense and defense. In the past, its scales were processed and used to make weapons and other commodities.');
INSERT INTO Pokemon VALUES (785,0,'Tapu Koko',7,70,115,85,130,95,75,'Although it''s called a guardian deity, if a person or Pokemon puts it in a bad mood, it will become a malevolent deity and attack.');
INSERT INTO Pokemon VALUES (786,0,'Tapu Lele',7,70,85,75,95,130,115,'As it flutters about, it scatters its strangely glowing scales. Touching them is said to restore good health on the spot.');
INSERT INTO Pokemon VALUES (787,0,'Tapu Bulu',7,70,130,115,75,85,95,'It pulls large trees up by the roots and swings them around. It causes vegetation to grow, and then it absorbs energy from the growth.');
INSERT INTO Pokemon VALUES (788,0,'Tapu Fini',7,70,75,115,85,95,130,'The dense fog it creates brings the downfall and destruction of its confused enemies. Ocean currents are the source of its energy.');
INSERT INTO Pokemon VALUES (789,0,'Cosmog',7,43,29,31,37,29,31,'Whether or not it''s a Pokemon from this world is a mystery. When it''s in a jam, it warps away to a safe place to hide.');
INSERT INTO Pokemon VALUES (790,0,'Cosmoem',7,43,29,131,37,29,131,'Motionless as if dead, its body is faintly warm to the touch. In the distant past, it was called the cocoon of the stars.');
INSERT INTO Pokemon VALUES (791,0,'Solgaleo',7,137,137,107,97,113,89,'It is said to live in another world. The intense light it radiates from the surface of its body can make the darkest of nights light up like midday.');
INSERT INTO Pokemon VALUES (792,0,'Lunala',7,137,113,89,97,137,107,'Said to live in another world, this Pokemon devours light, drawing the moonless dark veil of night over the brightness of day.');
INSERT INTO Pokemon VALUES (793,0,'Nihilego',7,109,53,47,103,127,131,'One of several mysterious Ultra Beasts. People on the street report observing those infested by it suddenly becoming violent.');
INSERT INTO Pokemon VALUES (794,0,'Buzzwole',7,107,139,139,79,53,53,'This Ultra Beast appeared from another world. It shows off its body, but whether that display is a boast or a threat remains unclear.');
INSERT INTO Pokemon VALUES (795,0,'Pheromosa',7,71,137,37,151,137,37,'One of the Ultra Beasts. It refuses to touch anything, perhaps because it senses some uncleanness in this world.');
INSERT INTO Pokemon VALUES (796,0,'Xurkitree',7,83,89,71,83,173,71,'One of the mysterious life-forms known as Ultra Beasts. Astonishing electric shocks emanate from its entire body, according to witnesses.');
INSERT INTO Pokemon VALUES (797,0,'Celesteela',7,97,101,103,61,107,101,'One kind of Ultra Beast. Witnesses have seen it burn down a forest by expelling gas from its two arms.');
INSERT INTO Pokemon VALUES (798,0,'Kartana',7,59,181,131,109,59,31,'One of the Ultra Beast life-forms, it was observed cutting down a gigantic steel tower with one stroke of its blade.');
INSERT INTO Pokemon VALUES (799,0,'Guzzlord',7,223,101,53,43,97,53,'A dangerous Ultra Beast, it appears to be eating constantly, but for some reason its droppings have never been found.');
INSERT INTO Pokemon VALUES (800,0,'Necrozma',7,97,107,101,79,127,89,'Light is apparently the source of its energy. It has an extraordinarily vicious disposition and is constantly firing off laser beams.');
INSERT INTO Pokemon VALUES (800,1,'Dusk Mane Necrozma',7,97,157,127,77,113,109,'This is Necrozma''s form while it''s absorbing the power of Solgaleo, making it extremely ferocious and impossible to control.');
INSERT INTO Pokemon VALUES (800,2,'Dawn Wings Necrozma',7,97,113,109,77,157,127,'Lunala no longer has a will of its own. Now under the control of Necrozma, it continuously expels all of its energy.');
INSERT INTO Pokemon VALUES (800,3,'Ultra Necrozma',7,97,167,97,129,167,97,'The light pouring out from all over its body affects living things and nature, impacting them in various ways.');
INSERT INTO Pokemon VALUES (801,0,'Magearna',7,80,95,115,65,130,115,'This artificial Pokemon, constructed more than 500 years ago, can understand human speech but cannot itself speak.');
INSERT INTO Pokemon VALUES (801,1,'Original Color Magearna',7,80,95,115,65,130,115,'This gorgeous Magearna looks as it did at the time of its invention. Its luxurious decoration pleased the king''s daughter.');
INSERT INTO Pokemon VALUES (802,0,'Marshadow',7,90,125,80,125,90,90,'Able to conceal itself in shadows, it never appears before humans, so its very existence was the stuff of myth.');
INSERT INTO Pokemon VALUES (803,0,'Poipole',7,67,73,67,73,73,67,'An Ultra Beast that lives in a different world, it cackles wildly as it sprays its opponents with poison from the needles on its head.');
INSERT INTO Pokemon VALUES (804,0,'Naganadel',7,73,73,73,121,127,73,'One kind of Ultra Beast, it fires a glowing, venomous liquid from its needles. This liquid is also immensely adhesive.');
INSERT INTO Pokemon VALUES (805,0,'Stakataka',7,61,131,211,13,53,101,'When stone walls started moving and attacking, the brute''s true identity was this mysterious life-form, which brings to mind an Ultra Beast.');
INSERT INTO Pokemon VALUES (806,0,'Blacephalon',7,53,127,53,107,151,79,'It slithers toward people. Then, without warning, it triggers the explosion of its own head. It''s apparently one kind of Ultra Beast.');
INSERT INTO Pokemon VALUES (807,0,'Zeraora',7,88,112,75,143,102,80,'It approaches its enemies at the speed of lightning, then tears them limb from limb with its sharp claws.');
INSERT INTO Pokemon VALUES (808,0,'Meltan',7,46,65,65,34,55,35,'It melts particles of iron and other metals found in the subsoil, so it can absorb them into its body of molten steel.');
INSERT INTO Pokemon VALUES (809,0,'Melmetal',7,135,143,143,34,80,65,'Revered long ago for its capacity to create iron from nothing, for some reason it has come back to life after 3,000 years.');
INSERT INTO Pokemon VALUES (810,0,'Grookey',8,50,65,50,65,40,40,'When it uses its special stick to strike up a beat, the sound waves produced carry revitalizing energy to the plants and flowers in the area.');
INSERT INTO Pokemon VALUES (811,0,'Thwackey',8,70,85,70,80,55,60,'When it''s drumming out rapid beats in battle, it gets so caught up in the rhythm that it won''t even notice that it''s already knocked out its opponent.');
INSERT INTO Pokemon VALUES (812,0,'Rillaboom',8,100,125,90,85,60,70,'By drumming, it taps into the power of its special tree stump. The roots of the stump follow its direction in battle.');
INSERT INTO Pokemon VALUES (813,0,'Scorbunny',8,50,71,40,69,40,40,'A warm-up of running around gets fire energy coursing through this Pokemon''s body. Once that happens, it''s ready to fight at full power.');
INSERT INTO Pokemon VALUES (814,0,'Raboot',8,65,86,60,94,55,60,'It kicks berries right off the branches of trees and then juggles them with its feet, practicing its footwork.');
INSERT INTO Pokemon VALUES (815,0,'Cinderace',8,80,116,75,119,65,75,'It juggles a pebble with its feet, turning it into a burning soccer ball. Its shots strike opponents hard and leave them scorched.');
INSERT INTO Pokemon VALUES (816,0,'Sobble',8,50,40,40,70,70,40,'When scared, this Pokemon cries. Its tears pack the chemical punch of 100 onions, and attackers won''t be able to resist weeping.');
INSERT INTO Pokemon VALUES (817,0,'Drizzile',8,65,60,55,90,95,55,'A clever combatant, this Pokemon battles using water balloons created with moisture secreted from its palms.');
INSERT INTO Pokemon VALUES (818,0,'Inteleon',8,70,85,65,120,125,65,'It has many hidden capabilities, such as fingertips that can shoot water and a membrane on its back that it can use to glide through the air.');
INSERT INTO Pokemon VALUES (819,0,'Skwovet',8,70,55,55,25,35,35,'It eats berries nonstop—a habit that has made it more resilient than it looks. It''ll show up on farms, searching for yet more berries.');
INSERT INTO Pokemon VALUES (820,0,'Greedent',8,120,95,95,20,55,75,'It stashes berries in its tail - so many berries that they fall out constantly. But this Pokemon is a bit slow-witted, so it doesn''t notice the loss.');
INSERT INTO Pokemon VALUES (821,0,'Rookidee',8,38,47,35,57,33,35,'Jumping nimbly about, this small-bodied Pokemon takes advantage of even the slightest opportunity to disorient larger opponents.');
INSERT INTO Pokemon VALUES (822,0,'Corvisquire',8,68,67,55,77,43,55,'Smart enough to use tools in battle, these Pokemon have been seen picking up rocks and flinging them or using ropes to wrap up enemies.');
INSERT INTO Pokemon VALUES (823,0,'Corviknight',8,98,87,105,67,53,85,'This Pokemon reigns supreme in the skies. The black luster of its steel body could drive terror into the heart of any foe.');
INSERT INTO Pokemon VALUES (824,0,'Blipbug',8,25,20,20,45,25,45,'Often found in gardens, this Pokemon has hairs on its body that it uses to assess its surroundings.');
INSERT INTO Pokemon VALUES (825,0,'Dottler',8,50,35,80,30,50,90,'It barely moves, but it''s still alive. Hiding in its shell without food or water seems to have awakened its psychic powers.');
INSERT INTO Pokemon VALUES (826,0,'Orbeetle',8,60,45,110,90,80,120,'It''s famous for its high level of intelligence, and the large size of its brain is proof that it also possesses immense psychic power.');
INSERT INTO Pokemon VALUES (827,0,'Nickit',8,40,28,28,50,47,52,'Aided by the soft pads on its feet, it silently raids the food stores of other Pokemon. It survives off its ill-gotten gains.');
INSERT INTO Pokemon VALUES (828,0,'Thievul',8,70,58,58,90,87,92,'It secretly marks potential targets with a scent. By following the scent, it stalks its targets and steals from them when they least expect it.');
INSERT INTO Pokemon VALUES (829,0,'Gossifleur',8,40,40,60,10,40,60,'It anchors itself in the ground with its single leg, then basks in the sun. After absorbing enough sunlight, its petals spread as it blooms brilliantly.');
INSERT INTO Pokemon VALUES (830,0,'Eldegoss',8,60,50,90,60,80,120,'The seeds attached to its cotton fluff are full of nutrients. It spreads them on the wind so that plants and other Pokemon can benefit from them.');
INSERT INTO Pokemon VALUES (831,0,'Wooloo',8,42,40,55,48,40,45,'Its curly fleece is such an effective cushion that this Pokemon could fall off a cliff and stand right back up at the bottom, unharmed.');
INSERT INTO Pokemon VALUES (832,0,'Dubwool',8,72,80,100,88,60,90,'Its majestic horns are meant only to impress the opposite gender. They never see use in battle.');
INSERT INTO Pokemon VALUES (833,0,'Chewtle',8,50,64,50,44,38,38,'It starts off battles by attacking with its rock-hard horn, but as soon as the opponent flinches, this Pokemon bites down and never lets go.');
INSERT INTO Pokemon VALUES (834,0,'Drednaw',8,90,115,90,74,48,68,'With jaws that can shear through steel rods, this highly aggressive Pokemon chomps down on its unfortunate prey.');
INSERT INTO Pokemon VALUES (835,0,'Yamper',8,59,45,50,26,40,50,'This gluttonous Pokemon only assists people with their work because it wants treats. As it runs, it crackles with electricity.');
INSERT INTO Pokemon VALUES (836,0,'Boltund',8,69,90,60,121,90,60,'This Pokemon generates electricity and channels it into its legs to keep them going strong. Boltund can run nonstop for three full days.');
INSERT INTO Pokemon VALUES (837,0,'Rolycoly',8,30,40,50,30,40,50,'Most of its body has the same composition as coal. Fittingly, this Pokemon was first discovered in coal mines about 400 years ago.');
INSERT INTO Pokemon VALUES (838,0,'Carkol',8,80,60,90,50,60,70,'By rapidly rolling its legs, it can travel at over 18 mph. The temperature of the flames it breathes exceeds 1,000 degrees Celsius.');
INSERT INTO Pokemon VALUES (839,0,'Coalossal',8,110,80,120,30,80,90,'While it''s engaged in battle, its mountain of coal will burn bright red, sending off sparks that scorch the surrounding area.');
INSERT INTO Pokemon VALUES (840,0,'Applin',8,40,40,80,20,40,40,'It spends its entire life inside an apple. It hides from its natural enemies, bird Pokemon, by pretending it''s just an apple and nothing more.');
INSERT INTO Pokemon VALUES (841,0,'Flapple',8,70,110,80,70,95,60,'It ate a sour apple, and that induced its evolution. In its cheeks, it stores an acid capable of causing chemical burns.');
INSERT INTO Pokemon VALUES (842,0,'Appletun',8,110,85,80,30,100,80,'Its body is covered in sweet nectar, and the skin on its back is especially yummy. Children used to have it as a snack.');
INSERT INTO Pokemon VALUES (843,0,'Silicobra',8,52,57,75,46,35,50,'It spews sand from its nostrils. While the enemy is blinded, it burrows into the ground to hide.');
INSERT INTO Pokemon VALUES (844,0,'Sandaconda',8,72,107,125,71,65,70,'Its unique style of coiling allows it to blast sand out of its sand sac more efficiently.');
INSERT INTO Pokemon VALUES (845,0,'Cramorant',8,70,85,55,85,85,95,'It''s so strong that it can knock out some opponents in a single hit, but it also may forget what it''s battling midfight.');
INSERT INTO Pokemon VALUES (845,1,'Gulping Form Cramorant',8,70,85,55,85,85,95,'Cramorant''s gluttony led it to try to swallow an Arrokuda whole, which in turn led to Cramorant getting an Arrokuda stuck in its throat.');
INSERT INTO Pokemon VALUES (845,2,'Gorging Form Cramorant',8,70,85,55,85,85,95,'This Cramorant has accidentally gotten a Pikachu lodged in its gullet. Cramorant is choking a little, but it isn''t really bothered.');
INSERT INTO Pokemon VALUES (846,0,'Arrokuda',8,41,63,40,66,40,30,'If it sees any movement around it, this Pokemon charges for it straightaway, leading with its sharply pointed jaw. It''s very proud of that jaw.');
INSERT INTO Pokemon VALUES (847,0,'Barraskewda',8,61,123,60,136,60,50,'This Pokemon has a jaw that''s as sharp as a spear and as strong as steel. Apparently Barraskewda''s flesh is surprisingly tasty, too.');
INSERT INTO Pokemon VALUES (848,0,'Toxel',8,40,38,35,40,54,35,'It manipulates the chemical makeup of its poison to produce electricity. The voltage is weak, but it can cause a tingling paralysis.');
INSERT INTO Pokemon VALUES (849,0,'Amped Form Toxtricity',8,75,98,70,75,114,70,'When this Pokemon sounds as if it''s strumming a guitar, it''s actually clawing at the protrusions on its chest to generate electricity.');
INSERT INTO Pokemon VALUES (849,1,'Low Key Form Toxtricity',8,75,98,70,75,114,70,'Capable of generating 15,000 volts of electricity, this Pokemon looks down on all that would challenge it.');
INSERT INTO Pokemon VALUES (850,0,'Sizzlipede',8,50,65,45,45,50,50,'It stores flammable gas in its body and uses it to generate heat. The yellow sections on its belly get particularly hot.');
INSERT INTO Pokemon VALUES (851,0,'Centiskorch',8,100,115,65,65,90,90,'While its burning body is already dangerous on its own, this excessively hostile Pokemon also has large and very sharp fangs.');
INSERT INTO Pokemon VALUES (852,0,'Clobbopus',8,50,68,60,32,50,50,'It''s very curious, but its means of investigating things is to try to punch them with its tentacles. The search for food is what brings it onto land.');
INSERT INTO Pokemon VALUES (853,0,'Grapploct',8,80,118,90,42,70,80,'A body made up of nothing but muscle makes the grappling moves this Pokemon performs with its tentacles tremendously powerful.');
INSERT INTO Pokemon VALUES (854,0,'Phony Form Sinistea',8,40,45,45,50,74,54,'The teacup in which this Pokemon makes its home is a famous piece of antique tableware. Many forgeries are in circulation.');
INSERT INTO Pokemon VALUES (854,1,'Antique Form Sinistea',8,40,45,45,50,74,54,'The swirl pattern in this Pokemon''s body is its weakness. If it gets stirred, the swirl loses its shape, and Sinistea gets dizzy.');
INSERT INTO Pokemon VALUES (855,0,'Phony Form Polteageist',8,60,65,65,70,134,114,'This species lives in antique teapots. Most pots are forgeries, but on rare occasions, an authentic work is found.');
INSERT INTO Pokemon VALUES (855,1,'Antique Form Polteageist',8,60,65,65,70,134,114,'Trainers Polteageist trusts will be allowed to experience its distinctive flavor and aroma firsthand by sampling just a tiny bit of its tea.');
INSERT INTO Pokemon VALUES (856,0,'Hatenna',8,42,30,45,39,56,53,'Via the protrusion on its head, it senses other creatures'' emotions. If you don''t have a calm disposition, it will never warm up to you.');
INSERT INTO Pokemon VALUES (857,0,'Hattrem',8,57,40,65,49,86,73,'Using the braids on its head, it pummels foes to get them to quiet down. One blow from those braids would knock out a professional boxer.');
INSERT INTO Pokemon VALUES (858,0,'Hatterene',8,57,90,95,29,136,103,'It emits psychic power strong enough to cause headaches as a deterrent to the approach of others.');
INSERT INTO Pokemon VALUES (859,0,'Impidimp',8,45,45,30,50,55,40,'Through its nose, it sucks in the emanations produced by people and Pokemon when they feel annoyed. It thrives off this negative energy.');
INSERT INTO Pokemon VALUES (860,0,'Morgrem',8,65,60,45,70,75,55,'With sly cunning, it tries to lure people into the woods. Some believe it to have the power to make crops grow.');
INSERT INTO Pokemon VALUES (861,0,'Grimmsnarl',8,95,120,65,60,95,75,'Its hairs work like muscle fibers. When its hairs unfurl, they latch on to opponents, ensnaring them as tentacles would.');
INSERT INTO Pokemon VALUES (862,0,'Obstagoon',8,93,90,101,95,60,81,'It evolved after experiencing numerous fights. While crossing its arms, it lets out a shout that would make any opponent flinch.');
INSERT INTO Pokemon VALUES (863,0,'Perrserker',8,70,110,100,50,50,60,'What appears to be an iron helmet is actually hardened hair. This Pokemon lives for the thrill of battle.');
INSERT INTO Pokemon VALUES (864,0,'Cursola',8,60,95,50,30,145,130,'Its shell is overflowing with its heightened otherworldly energy. The ectoplasm serves as protection for this Pokemon''s core spirit.');
INSERT INTO Pokemon VALUES (865,0,'Sirfetch''d',8,62,135,95,65,68,82,'After deflecting attacks with its hard leaf shield, it strikes back with its sharp leek stalk. The leek stalk is both weapon and food.');
INSERT INTO Pokemon VALUES (866,0,'Mr. Rime',8,80,85,75,70,110,100,'Its amusing movements make it very popular. It releases its psychic power from the pattern on its belly.');
INSERT INTO Pokemon VALUES (867,0,'Runerigus',8,58,95,145,30,50,105,'A powerful curse was woven into an ancient painting. After absorbing the spirit of a Yamask, the painting began to move.');
INSERT INTO Pokemon VALUES (868,0,'Milcery',8,45,40,40,34,50,61,'This Pokemon was born from sweet-smelling particles in the air. Its body is made of cream.');
INSERT INTO Pokemon VALUES (869,0,'Vanilla Cream Alcremie',8,65,60,75,64,110,121,'When Alcremie is content, the cream it secretes from its hands becomes sweeter and richer.');
INSERT INTO Pokemon VALUES (869,1,'Ruby Cream Alcremie',8,65,60,75,64,110,121,'The cells that compose its cream fluctuated suddenly during evolution, giving the cream a sweet and tart flavor.');
INSERT INTO Pokemon VALUES (869,2,'Matcha Cream Alcremie',8,65,60,75,64,110,121,'The cells that compose its cream fluctuated suddenly during evolution, giving the cream an aromatic flavor.');
INSERT INTO Pokemon VALUES (869,3,'Mint Cream Alcremie',8,65,60,75,64,110,121,'The cells that compose its cream fluctuated suddenly during evolution, giving the cream a refreshing flavor.');
INSERT INTO Pokemon VALUES (869,4,'Lemon Cream Alcremie',8,65,60,75,64,110,121,'The cells that compose its cream fluctuated suddenly during evolution, giving the cream a sour flavor.');
INSERT INTO Pokemon VALUES (869,5,'Salted Cream Alcremie',8,65,60,75,64,110,121,'The cells that compose its cream fluctuated suddenly during evolution, giving the cream a salty flavor.');
INSERT INTO Pokemon VALUES (869,6,'Ruby Swirl Alcremie',8,65,60,75,64,110,121,'The cells that compose its cream fluctuated suddenly during evolution, giving the cream a mixed flavor.');
INSERT INTO Pokemon VALUES (869,7,'Caramel Swirl Alcremie',8,65,60,75,64,110,121,'The cells that compose its cream fluctuated suddenly during evolution, giving the cream a bitter flavor.');
INSERT INTO Pokemon VALUES (869,8,'Rainbow Swirl Alcremie',8,65,60,75,64,110,121,'The cells that compose its cream fluctuated suddenly during evolution, giving the cream a complex flavor.');
INSERT INTO Pokemon VALUES (870,0,'Falinks',8,65,100,100,75,70,60,'The six of them work together as one Pokemon. Teamwork is also their battle strategy, and they constantly change their formation as they fight.');
INSERT INTO Pokemon VALUES (871,0,'Pincurchin',8,48,101,95,15,91,85,'It stores electricity in each spine. Even if one gets broken off, it still continues to emit electricity for at least three hours.');
INSERT INTO Pokemon VALUES (872,0,'Snom',8,30,25,35,20,45,30,'It spits out thread imbued with a frigid sort of energy and uses it to tie its body to branches, disguising itself as an icicle while it sleeps.');
INSERT INTO Pokemon VALUES (873,0,'Frosmoth',8,70,65,60,65,125,90,'It shows no mercy to any who desecrate fields and mountains. It will fly around on its icy wings, causing a blizzard to chase offenders away.');
INSERT INTO Pokemon VALUES (874,0,'Stonjourner',8,100,125,135,70,20,20,'Once a year, on a specific date and at a specific time, they gather out of nowhere and form up in a circle.');
INSERT INTO Pokemon VALUES (875,0,'Ice Face Eiscue',8,75,80,110,50,65,90,'It drifted in on the flow of ocean waters from a frigid place. It keeps its head iced constantly to make sure it stays nice and cold.');
INSERT INTO Pokemon VALUES (875,1,'Noice Face Eiscue',8,75,80,70,130,65,50,'The ice covering this Pokemon''s face has shattered, revealing a slightly worried expression that many people are enamored with.');
INSERT INTO Pokemon VALUES (876,0,'Male Indeedee',8,60,65,55,95,105,95,'It uses the horns on its head to sense the emotions of others. Males will act as valets for those they serve, looking after their every need.');
INSERT INTO Pokemon VALUES (876,1,'Female Indeedee',8,70,55,65,85,95,105,'They diligently serve people and Pokemon so they can gather feelings of gratitude. The females are particularly good at babysitting.');
INSERT INTO Pokemon VALUES (877,0,'Full Belly Mode Morpeko',8,58,95,58,97,70,58,'As it eats the seeds stored up in its pocket-like pouches, this Pokemon is not just satisfying its constant hunger. It''s also generating electricity.');
INSERT INTO Pokemon VALUES (877,1,'Hangry Mode Morpeko',8,58,95,58,97,70,58,'Hunger hormones affect its temperament. Until its hunger is appeased, it gets up to all manner of evil deeds.');
INSERT INTO Pokemon VALUES (878,0,'Cufant',8,72,80,49,40,40,49,'It digs up the ground with its trunk. It''s also very strong, being able to carry loads of over five tons without any problem at all.');
INSERT INTO Pokemon VALUES (879,0,'Copperajah',8,122,130,69,30,80,69,'These Pokemon live in herds. Their trunks have incredible grip strength, strong enough to crush giant rocks into powder.');
INSERT INTO Pokemon VALUES (880,0,'Dracozolt',8,90,100,90,75,80,70,'In ancient times, it was unbeatable thanks to its powerful lower body, but it went extinct anyway after it depleted all its plant-based food sources.');
INSERT INTO Pokemon VALUES (881,0,'Arctozolt',8,90,100,90,55,90,80,'The shaking of its freezing upper half is what generates its electricity. It has a hard time walking around.');
INSERT INTO Pokemon VALUES (882,0,'Dracovish',8,90,90,100,75,70,80,'Powerful legs and jaws made it the apex predator of its time. Its own overhunting of its prey was what drove it to extinction.');
INSERT INTO Pokemon VALUES (883,0,'Arctovish',8,90,90,100,55,80,90,'Though it''s able to capture prey by freezing its surroundings, it has trouble eating the prey afterward because its mouth is on top of its head.');
INSERT INTO Pokemon VALUES (884,0,'Duraludon',8,70,95,115,85,120,50,'Its body resembles polished metal, and it''s both lightweight and strong. The only drawback is that it rusts easily.');
INSERT INTO Pokemon VALUES (885,0,'Dreepy',8,28,60,30,82,40,30,'After being reborn as a ghost Pokemon, Dreepy wanders the areas it used to inhabit back when it was alive in prehistoric seas.');
INSERT INTO Pokemon VALUES (886,0,'Drakloak',8,68,80,50,102,60,50,'It''s capable of flying faster than 120 mph. It battles alongside Dreepy and dotes on them until they successfully evolve.');
INSERT INTO Pokemon VALUES (887,0,'Dragapult',8,88,120,75,142,100,75,'When it isn''t battling, it keeps Dreepy in the holes on its horns. Once a fight starts, it launches the Dreepy like supersonic missiles.');
INSERT INTO Pokemon VALUES (888,0,'Hero of Many Battles Zacian',8,92,130,115,138,80,115,'Known as a legendary hero, this Pokemon absorbs metal particles, transforming them into a weapon it uses to battle.');
INSERT INTO Pokemon VALUES (888,1,'Crowned Sword Zacian',8,92,170,115,148,80,115,'Able to cut down anything with a single strike, it became known as the Fairy King''s Sword, and it inspired awe in friend and foe alike.');
INSERT INTO Pokemon VALUES (889,0,'Hero of Many Battles Zamazenta',8,92,130,115,138,80,115,'This Pokemon slept for aeons while in the form of a statue. It was asleep for so long, people forgot that it ever existed.');
INSERT INTO Pokemon VALUES (889,1,'Crowned Shield Zamazenta',8,92,130,145,128,80,145,'Its ability to deflect any attack led to it being known as the Fighting Master''s Shield. It was feared and respected by all.');
INSERT INTO Pokemon VALUES (890,0,'Eternatus',8,140,85,95,130,145,95,'The core on its chest absorbs energy emanating from the lands of the Galar region. This energy is what allows Eternatus to stay active.');
INSERT INTO Pokemon VALUES (891,0,'Kubfu',8,60,90,60,72,53,50,'Kubfu trains hard to perfect its moves. The moves it masters will determine which form it takes when it evolves.');
INSERT INTO Pokemon VALUES (892,0,'Single Strike Style Urshifu',8,100,130,100,97,63,60,'Inhabiting the mountains of a distant region, this Pokemon races across sheer cliffs, training its legs and refining its moves.');
INSERT INTO Pokemon VALUES (892,1,'Rapid Strike Style Urshifu',8,100,130,100,97,63,60,'It''s believed that this Pokemon modeled its fighting style on the flow of a river—sometimes rapid, sometimes calm.');
INSERT INTO Pokemon VALUES (893,0,'Zarude',8,105,120,105,105,70,95,'Once the vines on Zarude''s body tear off, they become nutrients in the soil. This helps the plants of the forest grow.');
INSERT INTO Pokemon VALUES (894,0,'Regieleki',8,80,100,50,200,100,50,'This Pokemon is a cluster of electrical energy. It''s said that removing the rings on Regieleki''s body will unleash the Pokemon''s latent power.');
INSERT INTO Pokemon VALUES (895,0,'Regidrago',8,200,100,50,80,100,50,'Its body is composed of crystallized dragon energy. Regidrago is said to have the powers of every dragon Pokemon.');
INSERT INTO Pokemon VALUES (896,0,'Glastrier',8,100,145,130,30,65,110,'Glastrier has tremendous physical strength, and the mask of ice covering its face is 100 times harder than diamond.');
INSERT INTO Pokemon VALUES (897,0,'Spectrier',8,100,65,60,130,145,80,'As it dashes through the night, Spectrier absorbs the life-force of sleeping creatures. It craves silence and solitude.');
INSERT INTO Pokemon VALUES (898,0,'Calyrex',8,100,80,80,80,80,80,'Calyrex is a merciful Pokemon, capable of providing healing and blessings. It reigned over the Galar region in times of yore.');
INSERT INTO Pokemon VALUES (898,1,'Ice Rider Calyrex',8,100,165,150,50,85,130,'According to lore, this Pokemon showed no mercy to those who got in its way, yet it would heal its opponents'' wounds after battle.');
INSERT INTO Pokemon VALUES (898,2,'Shadow Rider Calyrex',8,100,85,80,150,165,100,'Legend says that by using its power to see all events from past to future, this Pokemon saved the creatures of a forest from a meteorite strike.');